import React, { useEffect, useState } from "react";
import { api, errMsg, today, hmm } from "../api";
import { ExportButtons } from "./Advances";
import { Chip, Modal, F, useToast, STATUS } from "../ui";
import { Avatar } from "./Employees";

export function DayEditor({ row, onClose, onSaved }) {
  const toast = useToast();
  const [st, setSt] = useState(row.manual_status || "");
  const [remark, setRemark] = useState(row.manual_remark || "");
  const [time, setTime] = useState("");
  const saveStatus = async () => {
    try { await api.put("/attendance/manual", { employee_id: row.employee_id, date: row.date, status: st || null, remark }); toast("Updated"); onSaved(); }
    catch (e) { toast(errMsg(e), true); }
  };
  const addPunch = async () => {
    if (!time) return;
    try { await api.post("/attendance/manual-punch", { employee_id: row.employee_id, date: row.date, time }); toast("Punch added"); onSaved(); }
    catch (e) { toast(errMsg(e), true); }
  };
  return (
    <Modal title={`${row.employee_name} — ${row.date}`} onClose={onClose}>
      <div className="kv" style={{ marginBottom: 16 }}>
        <dt>Punches</dt><dd className="mono">{(row.punches || []).join("  ·  ") || "none"}</dd>
        <dt>Calculated</dt><dd><Chip s={row.auto_status} /> {row.remark}</dd>
        <dt>Work / late / OT</dt><dd>{hmm(row.work_minutes)} h · {row.late_minutes || 0} min · {hmm(row.ot_minutes)} h</dd>
      </div>
      <h3>Add missed punch</h3>
      <div className="row" style={{ marginBottom: 18 }}><input type="time" value={time} onChange={(e) => setTime(e.target.value)} style={{ maxWidth: 160 }} /><button className="btn ghost" onClick={addPunch}>Add punch</button></div>
      <h3>Override status</h3>
      <div className="grid g2">
        <F label="Status"><select value={st} onChange={(e) => setSt(e.target.value)}><option value="">Automatic (from punches)</option>
          {["P", "HD", "A", "L", "LWP", "WO", "H"].map((s) => <option key={s} value={s}>{STATUS[s]}</option>)}</select></F>
        <F label="Remark"><input value={remark} onChange={(e) => setRemark(e.target.value)} placeholder="e.g. on field duty" /></F>
      </div>
      <div className="row" style={{ marginTop: 14, justifyContent: "flex-end" }}><button className="btn green" onClick={saveStatus}>Save status</button></div>
    </Modal>
  );
}

export default function Attendance() {
  const [date, setDate] = useState(today());
  const [rows, setRows] = useState([]);
  const [filter, setFilter] = useState("");
  const [q, setQ] = useState("");
  const [edit, setEdit] = useState(null);
  const load = () => api.get("/attendance/daily?date=" + date).then((r) => setRows(r.data.rows));
  useEffect(() => { load(); }, [date]); // eslint-disable-line
  const counts = rows.reduce((a, r) => ({ ...a, [r.status]: (a[r.status] || 0) + 1 }), {});
  const shown = rows.filter((r) => (!filter || r.status === filter || (filter === "late" && r.late_minutes > 0)) &&
    (!q || `${r.emp_code} ${r.employee_name} ${r.department}`.toLowerCase().includes(q.toLowerCase())));
  const shift = (n) => { const d = new Date(date); d.setDate(d.getDate() + n); setDate(d.toISOString().slice(0, 10)); };
  return (
    <>
      <div className="page-head">
        <div><h1>Daily attendance</h1><p>Click a row to correct a missed punch or override the status.</p></div>
        <div className="row">
          <button className="btn ghost" onClick={() => shift(-1)}>‹</button>
          <input type="date" value={date} onChange={(e) => setDate(e.target.value)} style={{ width: 170 }} />
          <button className="btn ghost" onClick={() => shift(1)}>›</button>
          <ExportButtons small={false} path="/reports/daily" query={`date=${date}`} name={`Daily_Attendance_${date}`} />
        </div>
      </div>
      <div className="row" style={{ marginBottom: 12 }}>
        <button className={"btn sm " + (filter === "" ? "" : "ghost")} onClick={() => setFilter("")}>All {rows.length}</button>
        {Object.keys(STATUS).filter((s) => counts[s]).map((s) => (
          <button key={s} className={"btn sm " + (filter === s ? "" : "ghost")} onClick={() => setFilter(s)}>{STATUS[s]} {counts[s]}</button>))}
        <button className={"btn sm " + (filter === "late" ? "" : "ghost")} onClick={() => setFilter("late")}>Late {rows.filter((r) => r.late_minutes > 0).length}</button>
        <div className="spacer" />
        <input placeholder="Search…" value={q} onChange={(e) => setQ(e.target.value)} style={{ maxWidth: 220 }} />
      </div>
      <div className="card flush"><div className="tbl-wrap"><table className="tbl">
        <thead><tr><th>ID</th><th>Employee</th><th>Shift</th><th>In</th><th>Out</th><th className="num">Work</th><th className="num">Late</th><th className="num">Early</th><th className="num">OT</th><th>Status</th><th>All punches</th></tr></thead>
        <tbody>{shown.map((r) => (
          <tr key={r.employee_id} style={{ cursor: "pointer" }} onClick={() => setEdit(r)}>
            <td className="mono">{r.emp_code}</td><td><div className="who"><Avatar e={r} size="sm" /><div><b>{r.employee_name}</b><div className="small muted">{r.department}</div></div></div></td>
            <td className="small muted">{r.shift_name}</td>
            <td className="mono">{r.in_time || "—"}</td><td className="mono">{r.out_time || "—"}</td>
            <td className="num mono">{r.work_minutes ? hmm(r.work_minutes) : "—"}</td>
            <td className="num">{r.late_minutes ? <span className="chip s-HD">{r.late_minutes}m</span> : ""}</td>
            <td className="num">{r.early_minutes ? <span className="chip s-HD">{r.early_minutes}m</span> : ""}</td>
            <td className="num mono">{r.ot_minutes ? hmm(r.ot_minutes) : ""}</td>
            <td><Chip s={r.status} />{r.manual_status && <span className="small muted"> (manual)</span>}{r.remark && <div className="small muted">{r.remark}</div>}</td>
            <td className="mono small muted">{(r.punches || []).join(" ")}</td>
          </tr>))}
          {!shown.length && <tr><td colSpan="11" className="empty">No records.</td></tr>}
        </tbody></table></div></div>
      {edit && <DayEditor row={edit} onClose={() => setEdit(null)} onSaved={() => { setEdit(null); load(); }} />}
    </>
  );
}
