import React, { useEffect, useState } from "react";
import { realApi, errMsg, LICENSE, setDemo } from "../api";
import { Modal, F, useToast, useConfirm } from "../ui";

function CopyBtn({ text, label = "Copy" }) {
  const [ok, setOk] = useState(false);
  return <button type="button" className="btn sm ghost" onClick={() => { try { navigator.clipboard.writeText(text); } catch { /* ignore */ } setOk(true); setTimeout(() => setOk(false), 1500); }}>{ok ? "Copied ✓" : label}</button>;
}

const fmtDate = (s) => (s ? new Date(s + (s.length === 10 ? "T00:00:00" : "")).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" }) : "—");
const SUPPORT = "Hayat Enterprises · Sales 96738 78652 · Services 84462 55253";

/* Activation: licence code (online) or paste the key (works offline). */
export function ActivateLicense({ onClose, reason, closeText = "Close" }) {
  const toast = useToast();
  const st = LICENSE || {};
  const [tab, setTab] = useState("key");
  const [key, setKey] = useState("");
  const [code, setCode] = useState(st.license?.code || "");
  const [server, setServer] = useState(st.license?.server || st.default_server || "");
  const [busy, setBusy] = useState(false);
  const done = (r) => { toast(`Licence active till ${fmtDate(r.data.license.valid_till)}`); setTimeout(() => { window.location.href = "/"; }, 700); };
  const go = async (fn) => { setBusy(true); try { done(await fn()); } catch (e) { toast(errMsg(e), true); } setBusy(false); };
  return (
    <Modal title="Activate Hayat HRMS on this computer" onClose={onClose}
      footer={<><button className="btn ghost" onClick={onClose}>{closeText}</button>
        {tab === "code" ? <button className="btn green" disabled={busy || !code || !server} onClick={() => go(() => realApi.post("/license/fetch", { code, server }))}>{busy ? "Checking…" : "Activate online"}</button>
          : <button className="btn green" disabled={busy || key.length < 40} onClick={() => go(() => realApi.post("/license/activate", { key }))}>{busy ? "Checking…" : "Activate"}</button>}</>}>
      {st.key_problem && <div className="note warn" style={{ marginBottom: 12 }}><b>Licence maker key problem:</b> {st.key_problem}</div>}
      {(reason || st.reason) && <div className="note warn" style={{ marginBottom: 12 }}>{reason || st.reason}</div>}
      <div className="lic-id">
        <div><div className="small muted">This computer's ID</div><div className="mono" style={{ fontSize: 18, fontWeight: 700 }}>{st.install_id || "—"}</div></div>
        <CopyBtn text={st.install_id || ""} />
      </div>
      <p className="small muted">Send this ID to Hayat Enterprises when you buy or renew. You get a licence code (short) and a licence key (long). Either one works.</p>
      <div className="tabs" style={{ marginTop: 6 }}>
        <button className={tab === "key" ? "on" : ""} onClick={() => setTab("key")}>Paste licence key</button>
        <button className={tab === "code" ? "on" : ""} onClick={() => setTab("code")}>Licence code (internet)</button>
      </div>
      {tab === "code" ? (
        <div className="grid">
          <F label="Licence code"><input className="mono" placeholder="HL-XXXX-XXXX" value={code} onChange={(e) => setCode(e.target.value.toUpperCase())} /></F>
          <F label="Licence server (from Hayat Enterprises)"><input placeholder="https://hrms.hayatcctv.com" value={server} onChange={(e) => setServer(e.target.value.trim())} /></F>
        </div>
      ) : (
        <F label="Licence key"><textarea className="mono" rows={5} placeholder="HAYAT1.…" value={key} onChange={(e) => setKey(e.target.value.trim())} style={{ fontSize: 11.5 }} /></F>
      )}
      <p className="small muted" style={{ marginBottom: 0 }}>{SUPPORT}</p>
    </Modal>
  );
}

/* First screen on an unlicensed computer (shown over the demo). */
export function LicenseGate() {
  const [open, setOpen] = useState(false);
  const st = LICENSE || {};
  const expired = st.license && st.license.days_left < 0;
  return (
    <>
      <div className="demo-bar lic">
        <b>{expired ? "Licence expired" : "Demo mode"}</b>
        <span>{expired ? `Your licence ended on ${fmtDate(st.license.valid_till)}. Your data is safe — renew to continue.` : "This computer is not activated. You are looking at sample data."}</span>
        <span className="spacer" />
        <button className="btn sm" onClick={() => setDemo(false)}>Exit demo — sign in to activate</button>
      </div>
      {open && <ActivateLicense onClose={() => setOpen(false)} closeText="Continue demo" />}
    </>
  );
}

/* On the real login page of a computer that is not activated. */
export function LoginLicenseNote() {
  const st = LICENSE || {};
  const expired = st.license && st.license.days_left < 0;
  return (
    <div className="note warn" style={{ marginBottom: 16 }}>
      <b>{expired ? "Licence expired." : "This computer is not activated."}</b>{" "}
      {expired ? `It ended on ${fmtDate(st.license.valid_till)}. Your data is safe — sign in and paste the new licence key.` : "Sign in, then paste your licence key to activate."}
      <div className="row" style={{ marginTop: 8 }}>
        <button type="button" className="btn sm ghost" onClick={() => setDemo(true)}>Try demo instead</button>
      </div>
    </div>
  );
}

/* Hayat Enterprises only: paste LICENSE_PRIVATE_KEY to make this PC / server the licence maker. */
function IssuerKeyCard({ st, reload }) {
  const toast = useToast();
  const ask = useConfirm();
  const [key, setKey] = useState("");
  const [busy, setBusy] = useState(false);
  const on = async () => {
    setBusy(true);
    try { const r = await realApi.post("/license/issuer-key", { key }); toast(r.data.message); setTimeout(() => { window.location.href = "/license"; }, 900); }
    catch (e) { toast(errMsg(e), true); }
    setBusy(false);
  };
  if (st.issuer) return (
    <div className="card" style={{ maxWidth: 820, marginBottom: 16 }}>
      <div className="row" style={{ justifyContent: "space-between" }}>
        <div><h2 style={{ margin: 0 }}>Licence maker <span className="chip s-P" style={{ marginLeft: 6 }}>ON</span></h2>
          <div className="small muted">This PC / server makes and renews licence keys (Shops page and the list below).</div></div>
        <button className="btn sm ghost danger" onClick={async () => (await ask({ title: "Switch off licence maker on this PC?", danger: true, okText: "Switch off", message: "The LICENSE_PRIVATE_KEY line is removed from backend\\.env. Keys already given keep working." })) && realApi.delete("/license/issuer-key").then(() => { window.location.href = "/license"; })}>Switch off</button>
      </div>
    </div>
  );
  return (
    <div className="card" style={{ maxWidth: 820, marginBottom: 16 }}>
      <h2 style={{ marginTop: 0 }}>Licence maker <span className="small muted">— Hayat Enterprises only</span></h2>
      <p className="small muted" style={{ marginTop: 0 }}>Paste the line from <b>Hayat-License-Private-Key.txt</b> (LICENSE_PRIVATE_KEY=…). It is saved in <span className="mono">backend\.env</span> and works straight away — this PC then makes licence keys for shops and never asks for a key itself.</p>
      <textarea className="mono" rows={2} placeholder="LICENSE_PRIVATE_KEY=…" value={key} onChange={(e) => setKey(e.target.value)} style={{ width: "100%", fontSize: 12 }} />
      <button className="btn green" style={{ marginTop: 8 }} disabled={busy || key.trim().length < 64} onClick={on}>{busy ? "Checking…" : "Activate licence maker"}</button>
    </div>
  );
}

/* Small banner when the licence is close to ending. */
export function LicenseWarning({ isSA }) {
  const st = LICENSE;
  const [open, setOpen] = useState(false);
  if (!st || !st.required || !st.licensed || !st.license || st.license.days_left > 15) return null;
  const d = st.license.days_left;
  return (
    <div className="trial-bar">
      {d === 0 ? "Your Hayat HRMS licence ends today." : `Your Hayat HRMS licence ends in ${d} day${d > 1 ? "s" : ""} (${fmtDate(st.license.valid_till)}).`} Call Hayat Enterprises on <span className="mono">96738 78652</span> to renew — the renewal reaches this computer automatically over the internet.
      {isSA && <button className="btn sm" style={{ marginLeft: 10 }} onClick={() => setOpen(true)}>Enter new key</button>}
      {open && <ActivateLicense onClose={() => setOpen(false)} />}
    </div>
  );
}

/* Super admin page: this computer's licence + (on your main server) making licence keys. */
export default function LicensePage() {
  const toast = useToast();
  const ask = useConfirm();
  const [st, setSt] = useState(null);
  const [lst, setLst] = useState(null);
  const [act, setAct] = useState(false);
  const [edit, setEdit] = useState(null);
  const [show, setShow] = useState(null);
  const [busy, setBusy] = useState("");
  const [q, setQ] = useState("");
  const load = async () => {
    const s = await realApi.get("/license/status"); setSt(s.data);
    if (s.data.issuer) { const l = await realApi.get("/admin/licenses"); setLst(l.data); }
  };
  useEffect(() => { load(); }, []);
  const run = async (label, fn, msg) => { setBusy(label); try { const r = await fn(); msg && toast(msg); await load(); return r; } catch (e) { toast(errMsg(e), true); } finally { setBusy(""); } };
  if (!st) return null;
  const L = st.license;
  const rows = (lst?.rows || []).filter((r) => !q || (r.customer + r.code + (r.phone || "") + (r.city || "")).toLowerCase().includes(q.toLowerCase()));
  const share = (r) => {
    const txt = `Hayat HRMS licence\nCustomer: ${r.customer}\nMachines: ${r.machines || "unlimited"} · Valid till ${fmtDate(r.valid_till)}\n\nLicence code: ${r.code}\nServer: ${lst.server}\n\nOr paste this key:\n${r.key}`;
    window.open(`https://wa.me/${(r.phone || "").replace(/\D/g, "").replace(/^(\d{10})$/, "91$1")}?text=${encodeURIComponent(txt)}`, "_blank");
  };
  return (
    <>
      <div className="page-head"><div><h1>Licence</h1><p>{st.issuer ? "Make, renew and manage licence keys for your customers." : "Licence of this computer."}</p></div></div>
      {!st.required && <IssuerKeyCard st={st} reload={load} />}

      {st.required && (
        <div className="card" style={{ maxWidth: 820, marginBottom: 16 }}>
          <div className="card-head" style={{ padding: 0, border: 0, marginBottom: 10 }}><h2 style={{ margin: 0 }}>This computer</h2>
            {st.licensed ? <span className="chip s-P">Active</span> : <span className="chip s-A">Not active</span>}</div>
          {L ? (
            <div className="grid g4">
              <div className="stat"><div className="k">Customer</div><div className="v sm">{L.customer}</div></div>
              <div className="stat"><div className="k">Valid till</div><div className="v sm">{fmtDate(L.valid_till)}</div><div className="small muted">{L.days_left >= 0 ? `${L.days_left} days left` : "expired"}</div></div>
              <div className="stat"><div className="k">Machines</div><div className="v sm">{st.machines_used} / {L.machines || "∞"}</div></div>
              <div className="stat"><div className="k">Shops</div><div className="v sm">{st.shops_used} / {L.shops || "∞"}</div></div>
            </div>) : <div className="note warn">{st.reason}</div>}
          {st.key_problem && <div className="note warn" style={{ marginTop: 8 }}><b>Licence maker key problem:</b> {st.key_problem}</div>}
          <div className="small muted" style={{ marginTop: 10 }}>
            Computer ID <span className="mono">{st.install_id}</span>{L && <> · code <span className="mono">{L.code}</span>{L.locked_to ? " · locked to this computer" : ""}</>}
            {st.last_check && <> · last online check {new Date(st.last_check).toLocaleString("en-IN")} ({st.last_check_msg})</>}
          </div>
          <div className="row" style={{ marginTop: 12 }}>
            <button className="btn green" onClick={() => setAct(true)}>{L ? "Enter new key / code" : "Activate"}</button>
            {L?.server && <button className="btn ghost" disabled={!!busy} onClick={() => run("chk", () => realApi.post("/license/fetch", {}), "Licence is up to date")}>{busy === "chk" ? "Checking…" : "Check for renewal now"}</button>}
            {L && <button className="btn ghost danger" onClick={async () => (await ask({ title: "Remove licence from this computer?", danger: true, okText: "Remove", message: "The software goes back to demo mode until a key is entered again. Data is not deleted." })) && run("rm", () => realApi.delete("/license"), "Licence removed").then(() => window.location.reload())}>Remove</button>}
          </div>
        </div>
      )}

      {st.required && !st.licensed && <IssuerKeyCard st={st} reload={load} />}
      {!st.required && !st.issuer && <div className="note" style={{ maxWidth: 820 }}>This server does not need a licence itself. Switch on the licence maker above to make keys for shops.</div>}

      {st.issuer && lst && (
        <div className="card flush">
          <div className="card-head">
            <div className="row"><button className="btn green sm" onClick={() => setEdit({ customer: "", phone: "", city: "", machines: 1, shops: 1, months: 12, lock: true, install_id: "", note: "" })}>+ New licence</button>
              <input placeholder="Search customer, code, phone" value={q} onChange={(e) => setQ(e.target.value)} style={{ maxWidth: 240 }} /></div>
            <span className="small muted">Licence server for customers: <span className="mono">{lst.server}</span> <CopyBtn text={lst.server} /></span>
          </div>
          <div className="tbl-wrap"><table className="tbl">
            <thead><tr><th>Customer</th><th>Code</th><th className="num">Machines</th><th className="num">Shops</th><th>Valid till</th><th>Computer</th><th>Last seen</th><th /></tr></thead>
            <tbody>{rows.map((r) => (
              <tr key={r.id} style={r.status === "revoked" ? { opacity: .55 } : null}>
                <td style={{ fontWeight: 700 }}>{r.customer}<div className="small muted">{[r.phone, r.city].filter(Boolean).join(" · ")}</div></td>
                <td className="mono">{r.code}{r.status === "revoked" && <div><span className="chip s-A">cancelled</span></div>}</td>
                <td className="num">{r.machines || "∞"}</td><td className="num">{r.shops || "∞"}</td>
                <td>{fmtDate(r.valid_till)}<div className={"small " + (r.days_left < 0 ? "" : "muted")} style={r.days_left < 0 ? { color: "var(--red)" } : r.days_left <= 15 ? { color: "#b45309" } : null}>{r.days_left < 0 ? "expired" : `${r.days_left} days left`}</div></td>
                <td className="small">{r.lock ? (r.install_id ? <span className="mono">{r.install_id}</span> : <span className="muted">locks on first use</span>) : <span className="muted">any computer</span>}</td>
                <td className="small muted">{r.last_seen ? new Date(r.last_seen).toLocaleDateString("en-IN") : "never"}{r.last_ip && <div className="mono">{r.last_ip}</div>}</td>
                <td className="row" style={{ justifyContent: "flex-end", flexWrap: "nowrap" }}>
                  {r.key && <button className="btn sm ghost" onClick={() => setShow(r)}>Key</button>}
                  <select className="sm" value="" disabled={!!busy} onChange={(e) => e.target.value && run("rn", () => realApi.post(`/admin/licenses/${r.id}/renew`, { months: Number(e.target.value) }), `Renewed — the customer's computer picks it up online, or send the new key`)} style={{ width: 92 }}>
                    <option value="">Renew…</option><option value="1">+1 month</option><option value="3">+3 months</option><option value="6">+6 months</option><option value="12">+1 year</option><option value="24">+2 years</option>
                  </select>
                  <button className="btn sm ghost" onClick={() => setEdit({ ...r })}>Edit</button>
                </td>
              </tr>))}
              {!rows.length && <tr><td colSpan="8" className="empty">No licences yet. Click “New licence”.</td></tr>}
            </tbody></table></div>
        </div>
      )}

      {act && <ActivateLicense onClose={() => { setAct(false); load(); }} />}
      {show && (
        <Modal title={`Licence — ${show.customer}`} onClose={() => setShow(null)}
          footer={<><button className="btn ghost" onClick={() => setShow(null)}>Close</button><button className="btn green" onClick={() => share(show)}>Send on WhatsApp</button></>}>
          <div className="grid g2" style={{ marginBottom: 10 }}>
            <div><div className="small muted">Licence code</div><div className="mono" style={{ fontSize: 20, fontWeight: 800 }}>{show.code} <CopyBtn text={show.code} /></div></div>
            <div><div className="small muted">Server</div><div className="mono small">{lst.server} <CopyBtn text={lst.server} /></div></div>
          </div>
          <div className="small muted">Licence key (works without internet) <CopyBtn text={show.key} /></div>
          <textarea readOnly className="mono" rows={6} value={show.key} style={{ width: "100%", fontSize: 11 }} onFocus={(e) => e.target.select()} />
          <p className="small muted">{show.machines || "Unlimited"} machine(s) · {show.shops || "unlimited"} shop(s) · valid till {fmtDate(show.valid_till)}. After a renewal or change, the customer's computer gets the new key by itself when it is online (checked daily, or “Check for renewal now”).</p>
          {show.history?.length > 0 && <details><summary className="small">History</summary>{show.history.map((h, i) => <div key={i} className="small muted">{new Date(h.at).toLocaleString("en-IN")} — {h.what}</div>)}</details>}
        </Modal>
      )}
      {edit && <EditLicense lic={edit} onClose={() => setEdit(null)} onSaved={(r) => { setEdit(null); load(); if (r && !edit.id) setShow(r); }} />}
    </>
  );
}

function EditLicense({ lic, onClose, onSaved }) {
  const toast = useToast();
  const ask = useConfirm();
  const [f, setF] = useState({ ...lic });
  const [busy, setBusy] = useState(false);
  const set = (k) => (e) => setF({ ...f, [k]: e.target.type === "checkbox" ? e.target.checked : e.target.value });
  const save = async (extra) => {
    setBusy(true);
    try {
      const body = { customer: f.customer, phone: f.phone, city: f.city, machines: Number(f.machines || 0), shops: Number(f.shops || 0),
        lock: f.lock, install_id: f.install_id || "", note: f.note, ...(f.id ? { valid_till: f.valid_till } : { months: Number(f.months || 12) }), ...extra };
      const r = f.id ? await realApi.put(`/admin/licenses/${f.id}`, body) : await realApi.post("/admin/licenses", body);
      toast(f.id ? "Licence saved" : "Licence created"); onSaved(r.data);
    } catch (e) { toast(errMsg(e), true); }
    setBusy(false);
  };
  return (
    <Modal title={f.id ? `Edit licence ${f.code}` : "New licence"} onClose={onClose}
      footer={<>
        {f.id && <button className="btn sm danger" style={{ marginRight: "auto" }} onClick={async () => (await ask({ title: f.status === "revoked" ? "Re-activate licence?" : "Cancel this licence?", danger: f.status !== "revoked", okText: f.status === "revoked" ? "Re-activate" : "Cancel licence", message: f.status === "revoked" ? "" : "The customer's computer goes to demo mode at its next online check. Offline computers keep working until the key's date." })) && save({ status: f.status === "revoked" ? "active" : "revoked" })}>{f.status === "revoked" ? "Re-activate" : "Cancel licence"}</button>}
        <button className="btn ghost" onClick={onClose}>Close</button>
        <button className="btn green" disabled={busy} onClick={() => save()}>{busy ? "Saving…" : f.id ? "Save" : "Create licence"}</button></>}>
      <div className="grid g2">
        <F label="Customer / shop name" span={2}><input value={f.customer} onChange={set("customer")} autoFocus /></F>
        <F label="Mobile (for WhatsApp)"><input value={f.phone || ""} onChange={set("phone")} /></F>
        <F label="City"><input value={f.city || ""} onChange={set("city")} /></F>
        <F label="Biometric machines allowed (0 = unlimited)"><input type="number" min="0" value={f.machines} onChange={set("machines")} /></F>
        <F label="Shops allowed (0 = unlimited)"><input type="number" min="0" value={f.shops} onChange={set("shops")} /></F>
        {f.id ? <F label="Valid till"><input type="date" value={f.valid_till} onChange={set("valid_till")} /></F>
          : <F label="Valid for"><select value={f.months} onChange={set("months")}><option value="1">1 month</option><option value="3">3 months</option><option value="6">6 months</option><option value="12">1 year</option><option value="24">2 years</option><option value="36">3 years</option></select></F>}
        <F label="Computer ID (optional)"><input className="mono" placeholder="XXXX-XXXX-XXXX" value={f.install_id || ""} onChange={(e) => setF({ ...f, install_id: e.target.value.toUpperCase() })} /></F>
        <label className="check" style={{ gridColumn: "span 2" }}><input type="checkbox" checked={!!f.lock} onChange={set("lock")} /> Lock to one computer (the key will not work on another PC; locks automatically on first online activation)</label>
        {f.id && f.lock && f.install_id && <div style={{ gridColumn: "span 2" }}><button className="btn sm ghost" onClick={() => setF({ ...f, install_id: "" })}>Free it to move to a new computer</button></div>}
        <F label="Note" span={2}><input value={f.note || ""} onChange={set("note")} placeholder="e.g. paid by UPI, 2 machines at Wadi" /></F>
      </div>
    </Modal>
  );
}
