import React, { useEffect, useState } from "react";
import { api, today, errMsg } from "../api";
import { useToast, useConfirm, Modal, F } from "../ui";
import { useAuth } from "../App";

export default function Punches() {
  const toast = useToast();
  const ask = useConfirm();
  const { me } = useAuth();
  const isOwner = ["owner", "superadmin"].includes(me.user.role);
  const [date, setDate] = useState(today());
  const [code, setCode] = useState("");
  const [rows, setRows] = useState([]);
  const [sel, setSel] = useState({});
  const [range, setRange] = useState(null);
  const [devices, setDevices] = useState([]);
  const load = () => { setSel({}); return api.get(`/punches?date=${date}${code ? "&emp_code=" + code : ""}`).then((r) => setRows(r.data)); };
  useEffect(() => { load(); }, [date]); // eslint-disable-line
  useEffect(() => { api.get("/devices").then((r) => setDevices(r.data.devices)).catch(() => {}); }, []);

  const NOTE = "Deleted machine punches are not downloaded again on the next sync. Attendance is recalculated.";
  const delOne = async (p) => {
    if (!(await ask({ title: "Delete this punch?", danger: true, okText: "Delete", message: `${p.employee_name} · ${p.ts}. ${NOTE}` }))) return;
    try { await api.delete("/punches/" + p.id); toast("Punch deleted"); load(); } catch (e) { toast(errMsg(e), true); }
  };
  const ids = Object.keys(sel).filter((k) => sel[k]);
  const delSelected = async () => {
    if (!(await ask({ title: `Delete ${ids.length} punch(es)?`, danger: true, okText: "Delete", message: NOTE }))) return;
    try { const r = await api.post("/punches/delete", { ids }); toast(`${r.data.deleted} punches deleted`); load(); } catch (e) { toast(errMsg(e), true); }
  };
  const countRange = async () => {
    try { const r = await api.post("/punches/delete-range", { ...range, dry_run: true }); setRange({ ...range, count: r.data.count }); }
    catch (e) { toast(errMsg(e), true); }
  };
  const delRange = async () => {
    try {
      const r = await api.post("/punches/delete-range", { ...range, dry_run: false });
      toast(`${r.data.deleted} punches deleted`); setRange(null); load();
    } catch (e) { toast(errMsg(e), true); }
  };
  const setR = (k) => (e) => setRange({ ...range, [k]: e.target.value, count: undefined });

  return (
    <>
      <div className="page-head">
        <div><h1>Punch logs</h1><p>Raw punches exactly as received from machines (duplicates are removed automatically).</p></div>
        <div className="row"><input type="date" value={date} onChange={(e) => setDate(e.target.value)} style={{ width: 170 }} />
          <input placeholder="Device ID" value={code} onChange={(e) => setCode(e.target.value)} style={{ width: 120 }} onKeyDown={(e) => e.key === "Enter" && load()} />
          <button className="btn ghost" onClick={load}>Filter</button>
          {isOwner && <button className="btn danger" onClick={() => setRange({ from_date: date, to_date: date, emp_code: code, device_id: "" })}>Delete by date range</button>}</div>
      </div>
      <div className="card flush">
        {ids.length > 0 && <div className="selbar"><b>{ids.length} selected</b><button className="btn sm danger" onClick={delSelected}>Delete selected</button><button className="btn sm link" onClick={() => setSel({})}>Clear</button></div>}
        <div className="tbl-wrap"><table className="tbl">
          <thead><tr>{isOwner && <th style={{ width: 36 }}><input type="checkbox" checked={rows.length > 0 && rows.every((p) => sel[p.id])} onChange={(e) => setSel(Object.fromEntries(rows.map((p) => [p.id, e.target.checked])))} /></th>}
            <th>Time</th><th>ID</th><th>Employee</th><th>Device</th><th>In/Out key</th><th>Verify</th><th>Source</th><th /></tr></thead>
          <tbody>{rows.map((p) => (
            <tr key={p.id}>
              {isOwner && <td><input type="checkbox" checked={!!sel[p.id]} onChange={(e) => setSel({ ...sel, [p.id]: e.target.checked })} /></td>}
              <td className="mono">{p.ts}</td><td className="mono">{p.emp_code}</td>
              <td style={{ fontWeight: 600, color: (p.employee_name || "").startsWith("—") ? "var(--red)" : undefined }}>{p.employee_name}</td>
              <td>{p.device_name}</td><td>{p.direction || ""}</td><td className="small muted">{p.verify}</td><td className="small">{p.source}{p.added_by ? ` by ${p.added_by}` : ""}</td>
              <td>{(isOwner || p.source === "manual") && <button className="btn sm danger" onClick={() => delOne(p)}>Delete</button>}</td></tr>))}
            {!rows.length && <tr><td colSpan="9" className="empty">No punches for this date.</td></tr>}
          </tbody></table></div>
      </div>
      {range && (
        <Modal title="Delete punches by date range" onClose={() => setRange(null)}
          footer={<><button className="btn ghost" onClick={() => setRange(null)}>Cancel</button>
            {range.count === undefined ? <button className="btn" onClick={countRange}>Count punches</button>
              : <button className="btn red" disabled={!range.count} onClick={delRange}>Delete {range.count} punches</button>}</>}>
          <div className="grid g2">
            <F label="From"><input type="date" value={range.from_date} onChange={setR("from_date")} /></F>
            <F label="To"><input type="date" value={range.to_date} onChange={setR("to_date")} /></F>
            <F label="Only this device ID (optional)"><input value={range.emp_code} onChange={setR("emp_code")} placeholder="all employees" /></F>
            <F label="Only this machine (optional)"><select value={range.device_id} onChange={setR("device_id")}><option value="">All machines</option>{devices.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}</select></F>
          </div>
          <p className="small muted" style={{ marginTop: 12 }}>{NOTE} Manual punches in the range are deleted too.</p>
          {range.count !== undefined && <div className={"note " + (range.count ? "warn" : "")}>{range.count ? `${range.count} punches match. This cannot be undone.` : "No punches match these filters."}</div>}
        </Modal>
      )}
    </>
  );
}
