import React, { useState, useCallback, createContext, useContext } from "react";

const ToastCtx = createContext(() => {});
export const useToast = () => useContext(ToastCtx);
export function ToastProvider({ children }) {
  const [t, setT] = useState(null);
  const show = useCallback((msg, err = false) => {
    setT({ msg, err });
    setTimeout(() => setT(null), err ? 6000 : 3500);
  }, []);
  return (
    <ToastCtx.Provider value={show}>
      {children}
      {t && <div className={"toast" + (t.err ? " err" : "")}>{t.msg}</div>}
    </ToastCtx.Provider>
  );
}

export function Modal({ title, onClose, children, footer, wide }) {
  return (
    <div className="modal-bg" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className={"modal" + (wide ? " wide" : "")}>
        <div className="modal-h"><h2>{title}</h2><button className="x" onClick={onClose}>×</button></div>
        <div className="modal-b">{children}</div>
        {footer && <div className="modal-f">{footer}</div>}
      </div>
    </div>
  );
}

export function F({ label, children, span }) {
  return <label className="f" style={span ? { gridColumn: `span ${span}` } : null}>{label}{children}</label>;
}

export const STATUS = {
  P: "Present", A: "Absent", HD: "Half Day", MIS: "Missed Punch", WO: "Weekly Off", H: "Holiday",
  L: "Paid Leave", LWP: "Leave w/o Pay", IN: "Inside", "-": "Not yet",
};
export const Chip = ({ s }) => <span className={"chip s-" + s}>{STATUS[s] || s}</span>;

export function Copy({ text }) {
  const [ok, setOk] = useState(false);
  return (
    <div className="code"><span>{text}</span>
      <button type="button" onClick={() => { navigator.clipboard.writeText(text); setOk(true); setTimeout(() => setOk(false), 1500); }}>{ok ? "Copied" : "Copy"}</button>
    </div>
  );
}

