/* ---------- confirmation dialog: const ask = useConfirm(); const r = await ask({...}); if (r) ... ---------- */
const ConfirmCtx = createContext(async () => null);
export const useConfirm = () => useContext(ConfirmCtx);
export function ConfirmProvider({ children }) {
  const [st, setSt] = useState(null);
  const ask = useCallback((opts) => new Promise((resolve) => {
    const values = {};
    (opts.options || []).forEach((o) => (values[o.key] = !!o.default));
    setSt({ ...opts, values, typed: "", resolve });
  }), []);
  const close = (res) => { st.resolve(res); setSt(null); };
  const blocked = st?.typeToConfirm && st.typed.trim().toLowerCase() !== st.typeToConfirm.trim().toLowerCase();
  return (
    <ConfirmCtx.Provider value={ask}>
      {children}
      {st && (
        <Modal title={st.title || "Are you sure?"} onClose={() => close(null)}
          footer={<><button className="btn ghost" onClick={() => close(null)}>Cancel</button>
            <button className={"btn " + (st.danger ? "red" : "green")} disabled={blocked} onClick={() => close(st.values)}>{st.okText || "Confirm"}</button></>}>
          {st.message && <p style={{ lineHeight: 1.55 }}>{st.message}</p>}
          {(st.options || []).map((o) => (
            <label className="check" key={o.key} style={{ margin: "10px 0", alignItems: "flex-start" }}>
              <input type="checkbox" checked={st.values[o.key]} onChange={(e) => setSt({ ...st, values: { ...st.values, [o.key]: e.target.checked } })} style={{ marginTop: 2 }} />
              <span>{o.label}{o.hint && <div className="small muted">{o.hint}</div>}</span>
            </label>
          ))}
          {st.typeToConfirm && <label className="f" style={{ marginTop: 12 }}>Type <b>{st.typeToConfirm}</b> to confirm
            <input value={st.typed} onChange={(e) => setSt({ ...st, typed: e.target.value })} autoFocus /></label>}
        </Modal>
      )}
    </ConfirmCtx.Provider>
  );
}
