import React, { useEffect, useState } from "react";
import { api, thisMonth } from "../api";
import { ExportButtons } from "./Advances";
import { DayEditor } from "./Attendance";

const SHORT = { P: "P", A: "A", HD: "½", MIS: "M", WO: "WO", H: "H", L: "L", LWP: "LW", IN: "IN", "-": "·" };

export default function Register() {
  const [month, setMonth] = useState(thisMonth());
  const [d, setD] = useState(null);
  const [edit, setEdit] = useState(null);
  const load = () => { setD(null); api.get("/attendance/monthly?month=" + month).then((r) => setD(r.data)); };
  useEffect(() => { load(); }, [month]); // eslint-disable-line
  const openCell = async (emp, date) => {
    const r = await api.get("/attendance/daily?date=" + date);
    const row = r.data.rows.find((x) => x.employee_id === emp.id);
    if (row) setEdit(row);
  };
  return (
    <>
      <div className="page-head">
        <div><h1>Monthly register</h1><p>P present · ½ half day · M missed punch · A absent · WO weekly off · H holiday · L leave. Dashed = manual. Click a cell to edit.</p></div>
        <div className="row">
          <input type="month" value={month} onChange={(e) => setMonth(e.target.value)} style={{ width: 170 }} />
          <ExportButtons small={false} path="/reports/monthly-register" query={`month=${month}`} name={`Attendance_Register_${month}`} />
        </div>
      </div>
      <div className="card flush"><div className="tbl-wrap" style={{ maxHeight: "72vh" }}>
        {!d ? <div className="empty">Loading…</div> : (
          <table className="reg">
            <thead><tr><th className="name">Employee</th>
              {d.days.map((x) => { const wd = new Date(x).getDay(); return <th key={x} className={wd === 0 ? "wo" : ""}>{x.slice(8)}<br /><span style={{ fontWeight: 400 }}>{"SMTWTFS"[wd]}</span></th>; })}
              <th style={{ padding: "0 8px" }}>Pres.</th><th style={{ padding: "0 8px" }}>Abs.</th><th style={{ padding: "0 8px" }}>Late</th><th style={{ padding: "0 8px" }}>OT h</th></tr></thead>
            <tbody>{d.rows.map((r) => (
              <tr key={r.employee.id}>
                <td className="name"><b>{r.employee.name}</b> <span className="mono muted">{r.employee.code}</span></td>
                {r.cells.map((c, i) => (
                  <td key={i} className={"c" + (c?.m ? " man" : "")} onClick={() => c && openCell(r.employee, d.days[i])} title={c ? `${c.in || ""} – ${c.out || ""}${c.late ? ` · late ${c.late}m` : ""}` : ""}>
                    {c ? <span className={"s-" + c.s}>{SHORT[c.s] || c.s}</span> : ""}
                  </td>))}
                <td className="mono" style={{ padding: "0 8px" }}>{r.summary.present_days}</td><td className="mono" style={{ padding: "0 8px" }}>{r.summary.A}</td>
                <td className="mono" style={{ padding: "0 8px" }}>{r.summary.late_days}</td><td className="mono" style={{ padding: "0 8px" }}>{(r.summary.ot_minutes / 60).toFixed(1)}</td>
              </tr>))}
              {!d.rows.length && <tr><td className="empty" colSpan={d.days.length + 5}>No employees.</td></tr>}
            </tbody>
          </table>)}
      </div></div>
      {edit && <DayEditor row={edit} onClose={() => setEdit(null)} onSaved={() => { setEdit(null); load(); }} />}
    </>
  );
}
