import React, { useEffect, useState } from "react";
import { api, errMsg } from "../api";
import { Modal, F, useToast } from "../ui";

const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const blank = { name: "", start: "09:00", end: "18:00", grace_minutes: 10, early_grace_minutes: 10, full_day_hours: 7, half_day_hours: 4, break_minutes: 0, ot_after_minutes: 30, weekly_off: [6], is_default: false };

export default function Shifts() {
  const toast = useToast();
  const [rows, setRows] = useState([]);
  const [edit, setEdit] = useState(null);
  const load = () => api.get("/shifts").then((r) => setRows(r.data));
  useEffect(() => { load(); }, []);
  const save = async () => {
    const b = { ...edit };
    ["grace_minutes", "early_grace_minutes", "full_day_hours", "half_day_hours", "break_minutes", "ot_after_minutes"].forEach((k) => (b[k] = Number(b[k] || 0)));
    try { if (b.id) await api.put("/shifts/" + b.id, b); else await api.post("/shifts", b); toast("Shift saved — attendance recalculates when opened"); setEdit(null); load(); }
    catch (e) { toast(errMsg(e), true); }
  };
  const del = async (s) => { try { await api.delete("/shifts/" + s.id); load(); } catch (e) { toast(errMsg(e), true); } };
  const set = (k) => (e) => setEdit({ ...edit, [k]: e.target.type === "checkbox" ? e.target.checked : e.target.value });
  return (
    <>
      <div className="page-head"><div><h1>Shifts</h1><p>Night shifts (e.g. 20:00 → 06:00) are supported — morning punches count for the previous day.</p></div>
        <button className="btn green" onClick={() => setEdit({ ...blank })}>+ Add shift</button></div>
      <div className="card flush"><table className="tbl">
        <thead><tr><th>Shift</th><th>Timing</th><th>Grace</th><th>Full / half day</th><th>Break</th><th>OT after</th><th>Weekly off</th><th /></tr></thead>
        <tbody>{rows.map((s) => (
          <tr key={s.id}><td style={{ fontWeight: 700 }}>{s.name} {s.is_default && <span className="chip s-P">default</span>}</td>
            <td className="mono">{s.start} – {s.end}</td><td>{s.grace_minutes} min</td><td>{s.full_day_hours} h / {s.half_day_hours} h</td>
            <td>{s.break_minutes} min</td><td>{s.ot_after_minutes} min</td><td>{(s.weekly_off || []).map((d) => DAYS[d]).join(", ") || "none"}</td>
            <td className="row" style={{ justifyContent: "flex-end" }}><button className="btn sm ghost" onClick={() => setEdit({ ...blank, ...s })}>Edit</button>
              {!s.is_default && <button className="btn sm danger" onClick={() => del(s)}>×</button>}</td></tr>))}</tbody></table></div>
      {edit && (
        <Modal title={edit.id ? "Edit shift" : "New shift"} onClose={() => setEdit(null)}
          footer={<><button className="btn ghost" onClick={() => setEdit(null)}>Cancel</button><button className="btn green" onClick={save}>Save</button></>}>
          <div className="grid g3">
            <F label="Name" span={3}><input value={edit.name} onChange={set("name")} /></F>
            <F label="Start"><input type="time" value={edit.start} onChange={set("start")} /></F>
            <F label="End"><input type="time" value={edit.end} onChange={set("end")} /></F>
            <F label="Break (min, deducted)"><input type="number" value={edit.break_minutes} onChange={set("break_minutes")} /></F>
            <F label="Late grace (min)"><input type="number" value={edit.grace_minutes} onChange={set("grace_minutes")} /></F>
            <F label="Early-leave grace (min)"><input type="number" value={edit.early_grace_minutes} onChange={set("early_grace_minutes")} /></F>
            <F label="OT counted after (min)"><input type="number" value={edit.ot_after_minutes} onChange={set("ot_after_minutes")} /></F>
            <F label="Full day if worked ≥ (hours)"><input type="number" step="0.5" value={edit.full_day_hours} onChange={set("full_day_hours")} /></F>
            <F label="Half day if worked ≥ (hours)"><input type="number" step="0.5" value={edit.half_day_hours} onChange={set("half_day_hours")} /></F>
          </div>
          <div className="small muted" style={{ margin: "14px 0 6px", fontWeight: 600 }}>Weekly off</div>
          <div className="row">{DAYS.map((d, i) => <label className="check" key={d}><input type="checkbox" checked={(edit.weekly_off || []).includes(i)}
            onChange={(e) => setEdit({ ...edit, weekly_off: e.target.checked ? [...(edit.weekly_off || []), i] : edit.weekly_off.filter((x) => x !== i) })} />{d}</label>)}</div>
          <label className="check" style={{ marginTop: 14 }}><input type="checkbox" checked={!!edit.is_default} onChange={set("is_default")} /> Default shift for employees without one</label>
        </Modal>
      )}
    </>
  );
}
