import React, { useState } from "react";
import { api, errMsg } from "../api";
import { Modal } from "../ui";

const MODE = { agent: "LAN agent", adms: "eSSL ADMS", hik_push: "Hikvision push", direct: "Static IP" };

/** "Send names to machines" — writes the names typed in the app onto the biometric machines. */
export default function PushNames({ employeeIds, deviceIds, onClose }) {
  const [busy, setBusy] = useState(false);
  const [res, setRes] = useState(null);
  const [err, setErr] = useState("");
  const run = async () => {
    setBusy(true); setErr("");
    try { const r = await api.post("/devices/push-names", { employee_ids: employeeIds, device_ids: deviceIds }); setRes(r.data); }
    catch (e) { setErr(errMsg(e)); }
    setBusy(false);
  };
  const who = employeeIds?.length ? `${employeeIds.length} selected employee(s)` : "all active employees";
  return (
    <Modal title="Send names to machines" onClose={onClose}
      footer={res ? <button className="btn green" onClick={onClose}>Done</button>
        : <><button className="btn ghost" onClick={onClose}>Cancel</button><button className="btn green" disabled={busy} onClick={run}>{busy ? "Sending…" : "Send names"}</button></>}>
      {!res ? (
        <div className="grid" style={{ gap: 10 }}>
          <p style={{ margin: 0 }}>Writes the names of <b>{who}</b> from this app onto {deviceIds?.length ? "this machine" : "every machine"}, so the right name shows on the machine's screen at each punch.</p>
          <ul className="small muted" style={{ margin: 0, paddingLeft: 18, lineHeight: 1.6 }}>
            <li>Only IDs already enrolled on the machine are renamed. Fingerprints, faces, cards, passwords and admin rights stay as they are.</li>
            <li>Older black-and-white eSSL models show only the first 8 letters.</li>
            <li>Hikvision terminals in “push” mode can't be written to. Use LAN agent or static IP mode for them.</li>
          </ul>
          {err && <div className="note warn">{err}</div>}
        </div>
      ) : (
        <div>
          {res.results.map((r, i) => (
            <div className="res-row" key={i}><span className={"dot " + (r.ok ? "online" : "error")} style={{ marginTop: 6 }} />
              <div style={{ flex: 1 }}><b>{r.device}</b> <span className="small muted">· {MODE[r.mode]}</span><div className="small">{r.message}</div></div></div>))}
          {!res.results.length && <div className="note warn">{res.message}</div>}
        </div>
      )}
    </Modal>
  );
}
