import React, { useState } from "react";
import { api, errMsg, DEMO, UNLICENSED } from "../api";
import { LoginLicenseNote } from "./License";
import emblem from "../assets/hayat-emblem.png";
import fullLogo from "../assets/hayat-full.png";
import { useAuth } from "../App";
import Signup from "./Signup";

export default function Login() {
  const { login } = useAuth();
  const [email, setEmail] = useState(DEMO ? "owner@sunrise-demo.in" : "");
  const [password, setPassword] = useState(DEMO ? "demo123" : "");
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const [mode, setMode] = useState(window.location.pathname.startsWith("/signup") ? "signup" : "login");
  const submit = async (e) => {
    e.preventDefault();
    setBusy(true); setErr("");
    try {
      const r = await api.post("/auth/login", { email, password });
      await login(r.data.token);
      window.history.replaceState(null, "", "/");
    } catch (ex) { setErr(errMsg(ex)); }
    setBusy(false);
  };
  return (
    <div className="login-wrap">
      <div className="login-art">
        <div className="row" style={{ gap: 10 }}>
          <span className="brand-mark lg"><img src={emblem} alt="" /></span>
          <b style={{ fontSize: 18 }}>Hayat HRMS</b>
        </div>
        <div>
          <h1>Every punch, every payslip — automatically.</h1>
          <div style={{ marginTop: 22 }}>
            <div className="feat"><i />eSSL · ZKTeco · Hikvision machines over LAN or static IP</div>
            <div className="feat"><i />Shift-wise attendance, late marks, overtime</div>
            <div className="feat"><i />One-click salary slips (PDF) on WhatsApp</div>
            <div className="feat"><i />Daily summary to owner, alerts to staff</div>
          </div>
        </div>
        <div className="login-brand"><img src={fullLogo} alt="Hayat Enterprises — CCTV, Biometrics, Security products" /></div>
        <div className="pulse" />
      </div>
      <div className="login-form">
        {mode === "signup" ? <Signup onBack={() => { setMode("login"); window.history.replaceState(null, "", "/login"); }} /> :
        <form onSubmit={submit}>
          <h1>Sign in</h1>
          <p className="muted">Owner, manager or super-admin login.</p>
          {UNLICENSED && <LoginLicenseNote />}
          <label className="f">Email<input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required autoFocus /></label>
          <label className="f">Password<input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required /></label>
          {err && <div className="note warn">{err}</div>}
          <button className="btn green" disabled={busy} style={{ justifyContent: "center", padding: 11 }}>{busy ? "Signing in…" : "Sign in"}</button>
          <div className="muted small" style={{ textAlign: "center" }}>New shop? <button type="button" className="btn link" onClick={() => { setMode("signup"); window.history.replaceState(null, "", "/signup"); }}>Create shop account</button></div>
        </form>}
      </div>
    </div>
  );
}
