import React, { useEffect, useState } from "react";
import { api, errMsg } from "../api";
import { F, useToast, useConfirm, Copy } from "../ui";
import { useAuth } from "../App";

export default function SignupAdmin() {
  const toast = useToast();
  const ask = useConfirm();
  const { setCompany, reloadCompanies } = useAuth();
  const [plat, setPlat] = useState(null);
  const [shops, setShops] = useState([]);
  const load = async () => {
    const [p, c] = await Promise.all([api.get("/admin/platform"), api.get("/admin/companies")]);
    setPlat(p.data); setShops(c.data.filter((x) => x.source === "signup"));
  };
  useEffect(() => { load(); }, []);
  if (!plat) return <div className="muted">Loading…</div>;
  const set = (k) => (e) => setPlat({ ...plat, [k]: e.target.type === "checkbox" ? e.target.checked : e.target.value });
  const save = async () => { try { const r = await api.put("/admin/platform", plat); setPlat(r.data); toast("Sign-up settings saved"); } catch (e) { toast(errMsg(e), true); } };
  const link = `${window.location.origin}/signup`;
  const pending = shops.filter((s) => s.pending);
  const done = shops.filter((s) => !s.pending);
  const approve = async (s) => { try { const r = await api.post(`/admin/companies/${s.id}/approve`); toast(`${s.name} approved${r.data.valid_till ? ` — trial till ${r.data.valid_till}` : ""}`); load(); reloadCompanies(); } catch (e) { toast(errMsg(e), true); } };
  const reject = async (s) => {
    if (!(await ask({ title: `Reject ${s.name}?`, danger: true, okText: "Reject and delete", typeToConfirm: s.name, message: "The shop and its login are deleted." }))) return;
    try { await api.post(`/admin/companies/${s.id}/delete`, { confirm_name: s.name }); toast("Sign-up rejected"); load(); reloadCompanies(); } catch (e) { toast(errMsg(e), true); }
  };
  const daysLeft = (d) => d ? Math.ceil((new Date(d) - new Date()) / 86400000) : null;
  const waText = `Manage staff attendance, salary slips and WhatsApp alerts from your biometric machine. Create your free shop account: ${link}`;

  return (
    <>
      <div className="page-head">
        <div><h1>Shop sign-up</h1><p>Let shops create their own account from the login page. Each new shop gets its own owner login, devices and staff.</p></div>
        <span className={"chip " + (plat.allow_signup ? "s-P" : "s-A")}>{plat.allow_signup ? "Sign-up open" : "Sign-up closed"}</span>
      </div>

      <div className="grid g2" style={{ marginBottom: 14 }}>
        <div className="card">
          <h2>Settings</h2>
          <div className="grid" style={{ gap: 12 }}>
            <label className="check"><input type="checkbox" checked={!!plat.allow_signup} onChange={set("allow_signup")} /> Allow new shops to sign up</label>
            <label className="check" style={{ alignItems: "flex-start" }}><input type="checkbox" checked={!!plat.require_approval} onChange={set("require_approval")} style={{ marginTop: 2 }} />
              <span>New shops need my approval (recommended)<div className="small muted">Every sign-up comes to “Waiting for approval” below. The shop sees a waiting screen until you approve it, and its free trial starts on the day you approve. Untick to let shops start straight away.</div></span></label>
            <div className="grid g3">
              <F label="Free trial (days, 0 = no expiry)"><input type="number" value={plat.trial_days} onChange={set("trial_days")} /></F>
              <F label="Devices per shop"><input type="number" value={plat.default_max_devices} onChange={set("default_max_devices")} /></F>
              <F label="Employees per shop"><input type="number" value={plat.default_max_employees} onChange={set("default_max_employees")} /></F>
            </div>
            <F label="Support phone (shown to shops)"><input value={plat.support_phone} onChange={set("support_phone")} /></F>
            <div><button className="btn green" onClick={save}>Save settings</button></div>
          </div>
        </div>
        <div className="card">
          <h2>Share the sign-up link</h2>
          <div className="grid" style={{ gap: 10 }}>
            <Copy text={link} />
            <div className="small muted">Ready-to-send WhatsApp message</div>
            <Copy text={waText} />
            <div className="row"><a className="btn ghost sm" href={link} target="_blank" rel="noreferrer">Open sign-up page ↗</a>
              <a className="btn ghost sm" href={`https://wa.me/?text=${encodeURIComponent(waText)}`} target="_blank" rel="noreferrer">Share on WhatsApp ↗</a></div>
            <p className="small muted" style={{ margin: 0 }}>The same page opens from “Create shop account” on the login screen.</p>
          </div>
        </div>
      </div>

      {pending.length > 0 && (
        <div className="card flush" style={{ marginBottom: 14, borderColor: "#fde68a" }}>
          <div className="card-head" style={{ background: "#fffbeb" }}><h2>Waiting for approval <span className="chip s-HD">{pending.length}</span></h2></div>
          <div className="tbl-wrap"><table className="tbl"><thead><tr><th>Shop</th><th>Owner</th><th>Mobile</th><th>Signed up</th><th /></tr></thead>
            <tbody>{pending.map((s) => (
              <tr key={s.id}><td style={{ fontWeight: 700 }}>{s.name}<div className="small muted">{s.city}</div></td>
                <td>{s.owner?.name}<div className="small muted">{s.owner?.email}</div></td><td className="mono">{s.phone}</td>
                <td className="small">{new Date(s.created_at).toLocaleString("en-IN", { dateStyle: "medium", timeStyle: "short" })}</td>
                <td className="row" style={{ justifyContent: "flex-end" }}><button className="btn sm green" onClick={() => approve(s)}>Approve</button><button className="btn sm danger" onClick={() => reject(s)}>Reject</button></td></tr>))}
            </tbody></table></div>
        </div>
      )}

      <div className="card flush">
        <div className="card-head"><h2>Shops that signed up</h2><span className="small muted">{done.length} shop(s)</span></div>
        <div className="tbl-wrap"><table className="tbl"><thead><tr><th>Shop</th><th>Owner</th><th>Mobile</th><th className="num">Staff</th><th className="num">Devices</th><th>Plan till</th><th>Signed up</th><th /></tr></thead>
          <tbody>{done.map((s) => {
            const dl = daysLeft(s.valid_till);
            return (
              <tr key={s.id}><td style={{ fontWeight: 700 }}>{s.name}<div className="small muted">{s.city}</div></td>
                <td>{s.owner?.name}<div className="small muted">{s.owner?.email}</div></td><td className="mono">{s.phone}</td>
                <td className="num">{s.employees}</td><td className="num">{s.devices}</td>
                <td>{s.valid_till ? <span className={"chip " + (dl < 0 ? "s-A" : dl <= 3 ? "s-HD" : "s-P")}>{dl < 0 ? "ended " : ""}{s.valid_till}</span> : "—"}{s.active === false && <span className="chip s-A" style={{ marginLeft: 4 }}>suspended</span>}</td>
                <td className="small">{new Date(s.created_at).toLocaleDateString("en-IN", { dateStyle: "medium" })}</td>
                <td><button className="btn sm" onClick={() => setCompany(s.id)}>Open →</button></td></tr>);
          })}
            {!done.length && <tr><td colSpan="8" className="empty">No shop has signed up yet. Share the link above.</td></tr>}
          </tbody></table></div>
      </div>
      <p className="small muted" style={{ marginTop: 10 }}>To extend a plan, change limits or suspend a shop, use Edit on the Shops page.</p>
    </>
  );
}
