import React, { useEffect, useState } from "react";
import { api, errMsg } from "../api";
import { useAuth } from "../App";

export default function Signup({ onBack }) {
  const { login } = useAuth();
  const [info, setInfo] = useState(null);
  const [f, setF] = useState({ shop_name: "", owner_name: "", mobile: "", email: "", city: "", password: "" });
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  useEffect(() => { api.get("/public/signup-info").then((r) => setInfo(r.data)).catch(() => setInfo({ allow_signup: false })); }, []);
  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });
  const submit = async (e) => {
    e.preventDefault();
    setBusy(true); setErr("");
    try {
      const r = await api.post("/auth/register-shop", f);
      await login(r.data.token);
      window.history.replaceState(null, "", "/");
    } catch (ex) { setErr(errMsg(ex)); }
    setBusy(false);
  };
  if (!info) return null;
  return (
    <form onSubmit={submit}>
      <h1>Create shop account</h1>
      {info.allow_signup ? <>
        <p className="muted">Connect your biometric machine, add staff and send salary slips on WhatsApp.
          {info.require_approval ? ` Your account opens after Hayat Enterprises approves it${info.trial_days ? `, with a free ${info.trial_days}-day trial` : ""}.` : info.trial_days ? ` Free for ${info.trial_days} days.` : ""}</p>
        <label className="f">Shop / business name<input id="su-shop" value={f.shop_name} onChange={set("shop_name")} required autoFocus /></label>
        <div className="grid g2" style={{ gap: 12 }}>
          <label className="f">Your name<input id="su-name" value={f.owner_name} onChange={set("owner_name")} /></label>
          <label className="f">City<input id="su-city" value={f.city} onChange={set("city")} /></label>
        </div>
        <label className="f">Mobile (WhatsApp)<input id="su-mobile" value={f.mobile} onChange={set("mobile")} inputMode="tel" required /></label>
        <label className="f">Email (your login)<input id="su-email" type="email" value={f.email} onChange={set("email")} required /></label>
        <label className="f">Password<input id="su-pass" type="password" value={f.password} onChange={set("password")} minLength={6} required /></label>
        {err && <div className="note warn">{err}</div>}
        <button className="btn green" disabled={busy} style={{ justifyContent: "center", padding: 11 }}>{busy ? "Sending…" : info.require_approval ? "Send for approval" : "Create shop account"}</button>
      </> : <div className="note">New sign-ups are closed. Call <b className="mono">{info.support_phone}</b> to open a shop account.</div>}
      <button type="button" className="btn link" onClick={onBack}>← I already have an account</button>
    </form>
  );
}
