import React, { useEffect, useMemo, useState } from "react";
import { api, errMsg, today } from "../api";
import { Modal, F, useToast } from "../ui";
import { Avatar } from "./Employees";

const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const addDays = (ds, n) => { const d = new Date(ds + "T00:00:00Z"); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const monday = (ds) => { const wd = (new Date(ds + "T00:00:00Z").getUTCDay() + 6) % 7; return addDays(ds, -wd); };

export default function Roster() {
  const toast = useToast();
  const [start, setStart] = useState(monday(today()));
  const [weeks, setWeeks] = useState(1);
  const [d, setD] = useState(null);
  const [changes, setChanges] = useState({});
  const [sel, setSel] = useState({});
  const [tool, setTool] = useState(null);
  const [busy, setBusy] = useState(false);
  const end = addDays(start, weeks * 7 - 1);

  const load = () => { setD(null); setChanges({}); api.get(`/roster?from_date=${start}&to_date=${end}`).then((r) => setD(r.data)).catch((e) => toast(errMsg(e), true)); };
  useEffect(() => { load(); }, [start, weeks]); // eslint-disable-line
  const shiftName = useMemo(() => Object.fromEntries((d?.shifts || []).map((s) => [s.id, s.name])), [d]);
  const short = (n) => (n || "").replace(/\s*\(.*\)/, "").slice(0, 12);

  const cellValue = (eid, i, c) => {
    const k = `${eid}|${d.days[i]}`;
    if (k in changes) return changes[k];
    return c.off ? "OFF" : c.shift_id;
  };
  const setCell = (eid, i, v) => setChanges({ ...changes, [`${eid}|${d.days[i]}`]: v });
  const save = async () => {
    setBusy(true);
    try {
      const cells = Object.entries(changes).map(([k, v]) => { const [employee_id, date] = k.split("|"); return { employee_id, date, shift_id: v }; });
      await api.put("/roster", { cells });
      toast(`${cells.length} change(s) saved — attendance recalculated`); load();
    } catch (e) { toast(errMsg(e), true); }
    setBusy(false);
  };
  const ids = Object.keys(sel).filter((k) => sel[k]);
  const dirty = Object.keys(changes).length;

  return (
    <>
      <div className="page-head">
        <div><h1>Shift roster</h1><p>Change anyone's shift or weekly off for any day. Green outline = set in the roster; others follow the employee's regular shift.</p></div>
        <div className="row">
          <button className="btn ghost" onClick={() => setStart(addDays(start, -7))}>‹</button>
          <input type="date" value={start} onChange={(e) => e.target.value && setStart(monday(e.target.value))} style={{ width: 170 }} />
          <button className="btn ghost" onClick={() => setStart(addDays(start, 7))}>›</button>
          <div className="seg">{[1, 2, 4].map((w) => <button key={w} className={weeks === w ? "on" : ""} onClick={() => setWeeks(w)}>{w} wk</button>)}</div>
        </div>
      </div>
      <div className="row" style={{ marginBottom: 12 }}>
        <button className="btn" disabled={!ids.length} onClick={() => setTool({ kind: "change", shift_id: d?.shifts[0]?.id, from_date: today(), note: "" })}>Change shift from a date</button>
        <button className="btn ghost" disabled={!ids.length} onClick={() => setTool({ kind: "weekly", from_date: start, to_date: addDays(start, 27), week: ["", "", "", "", "", "", ""] })}>Weekly pattern</button>
        <button className="btn ghost" disabled={!ids.length} onClick={() => setTool({ kind: "rotate", from_date: start, to_date: addDays(start, 55), rotation: [d?.shifts[0]?.id, d?.shifts[1]?.id || ""], every: 7, off_days: [6] })}>Rotate shifts</button>
        <span className="small muted">{ids.length ? `${ids.length} selected` : "Tick employees to use these tools"}</span>
        <div className="spacer" />
        {dirty > 0 && <><button className="btn ghost" onClick={() => setChanges({})}>Undo {dirty}</button><button className="btn green" disabled={busy} onClick={save}>Save {dirty} change(s)</button></>}
      </div>
      <div className="card flush"><div className="tbl-wrap" style={{ maxHeight: "70vh" }}>
        {!d ? <div className="empty">Loading…</div> : (
          <table className="roster">
            <thead><tr>
              <th className="name"><label className="check"><input type="checkbox" checked={d.rows.length > 0 && d.rows.every((r) => sel[r.employee.id])} onChange={(e) => setSel(Object.fromEntries(d.rows.map((r) => [r.employee.id, e.target.checked])))} /> Employee</label></th>
              {d.days.map((x) => { const wd = (new Date(x + "T00:00:00Z").getUTCDay() + 6) % 7; return <th key={x} className={x === today() ? "today" : ""}>{DAYS[wd]}<br />{x.slice(8)}/{x.slice(5, 7)}</th>; })}
            </tr></thead>
            <tbody>{d.rows.map((r) => (
              <tr key={r.employee.id}>
                <td className="name"><label className="check"><input type="checkbox" checked={!!sel[r.employee.id]} onChange={(e) => setSel({ ...sel, [r.employee.id]: e.target.checked })} />
                  <span className="who"><Avatar e={r.employee} size="sm" /><span><b>{r.employee.name}</b><div className="small muted mono">{r.employee.code}</div></span></span></label></td>
                {r.cells.map((c, i) => {
                  const v = cellValue(r.employee.id, i, c);
                  const changed = `${r.employee.id}|${d.days[i]}` in changes;
                  return (
                    <td key={i}>
                      <select value={v || ""} className={(v === "OFF" ? "off " : "") + (c.set || changed ? "set" : "")} onChange={(e) => setCell(r.employee.id, i, e.target.value)} title={c.set ? "Set in roster" : "Regular shift"}>
                        {d.shifts.map((s) => <option key={s.id} value={s.id}>{short(s.name)}</option>)}
                        <option value="OFF">Week off</option>
                        {c.set && <option value="">↺ Regular</option>}
                      </select>
                    </td>);
                })}
              </tr>))}
              {!d.rows.length && <tr><td className="empty" colSpan={d.days.length + 1}>No employees yet.</td></tr>}
            </tbody>
          </table>)}
      </div></div>
      {tool && <RosterTool tool={tool} setTool={setTool} shifts={d?.shifts || []} ids={ids} shiftName={shiftName} onDone={() => { setTool(null); load(); }} />}
    </>
  );
}

function RosterTool({ tool, setTool, shifts, ids, onDone }) {
  const toast = useToast();
  const [busy, setBusy] = useState(false);
  const set = (k) => (e) => setTool({ ...tool, [k]: e.target.value });
  const run = async () => {
    setBusy(true);
    try {
      if (tool.kind === "change") {
        const r = await api.post("/shifts/change", { employee_ids: ids, shift_id: tool.shift_id, from_date: tool.from_date, note: tool.note });
        toast(`Shift changed for ${r.data.changed} employee(s) from ${tool.from_date}`);
      } else {
        const r = await api.post("/roster/pattern", { ...tool, mode: tool.kind, employee_ids: ids, rotation: (tool.rotation || []).filter(Boolean) });
        toast(`${r.data.saved} roster days saved`);
      }
      onDone();
    } catch (e) { toast(errMsg(e), true); }
    setBusy(false);
  };
  const opts = (blank) => <>{blank}{shifts.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</>;
  const title = { change: "Change shift from a date", weekly: "Weekly pattern", rotate: "Rotate shifts" }[tool.kind];
  return (
    <Modal title={`${title} — ${ids.length} employee(s)`} onClose={() => setTool(null)}
      footer={<><button className="btn ghost" onClick={() => setTool(null)}>Cancel</button><button className="btn green" disabled={busy} onClick={run}>{busy ? "Saving…" : "Apply"}</button></>}>
      {tool.kind === "change" && <div className="grid g2">
        <F label="New shift"><select value={tool.shift_id} onChange={set("shift_id")}>{opts()}</select></F>
        <F label="From date"><input type="date" value={tool.from_date} onChange={set("from_date")} /></F>
        <F label="Reason (optional)" span={2}><input value={tool.note} onChange={set("note")} placeholder="e.g. moved to night duty" /></F>
        <p className="small muted" style={{ gridColumn: "span 2", margin: 0 }}>A permanent change. Days before the date keep the old shift, so past attendance and salary don't change. Day-wise roster entries still win.</p>
      </div>}
      {tool.kind !== "change" && <div className="grid g2" style={{ marginBottom: 14 }}>
        <F label="From"><input type="date" value={tool.from_date} onChange={set("from_date")} /></F>
        <F label="To"><input type="date" value={tool.to_date} onChange={set("to_date")} /></F>
      </div>}
      {tool.kind === "weekly" && <>
        <div className="grid" style={{ gridTemplateColumns: "repeat(7, minmax(0,1fr))", gap: 6 }}>
          {DAYS.map((dn, i) => <F key={dn} label={dn}><select value={tool.week[i]} onChange={(e) => { const w = [...tool.week]; w[i] = e.target.value; setTool({ ...tool, week: w }); }}>
            {opts(<><option value="">No change</option><option value="OFF">Week off</option><option value="CLEAR">↺ Regular</option></>)}</select></F>)}
        </div>
        <p className="small muted">Example: give Sunday as work day and Tuesday as week off for the next 4 weeks.</p>
      </>}
      {tool.kind === "rotate" && <>
        <div className="grid g2">
          <F label="1st shift"><select value={tool.rotation[0] || ""} onChange={(e) => setTool({ ...tool, rotation: [e.target.value, tool.rotation[1] || "", tool.rotation[2] || ""] })}>{opts()}</select></F>
          <F label="2nd shift"><select value={tool.rotation[1] || ""} onChange={(e) => setTool({ ...tool, rotation: [tool.rotation[0], e.target.value, tool.rotation[2] || ""] })}>{opts(<option value="">—</option>)}</select></F>
          <F label="3rd shift (optional)"><select value={tool.rotation[2] || ""} onChange={(e) => setTool({ ...tool, rotation: [tool.rotation[0], tool.rotation[1], e.target.value] })}>{opts(<option value="">—</option>)}</select></F>
          <F label="Change shift every (days)"><input type="number" min="1" value={tool.every} onChange={set("every")} /></F>
        </div>
        <div className="small muted" style={{ margin: "12px 0 6px", fontWeight: 600 }}>Week off on</div>
        <div className="row">{DAYS.map((dn, i) => <label className="check" key={dn}><input type="checkbox" checked={tool.off_days.includes(i)}
          onChange={(e) => setTool({ ...tool, off_days: e.target.checked ? [...tool.off_days, i] : tool.off_days.filter((x) => x !== i) })} />{dn}</label>)}</div>
        <p className="small muted">Example: Day shift one week, Night shift next week, repeating — Sunday off.</p>
      </>}
    </Modal>
  );
}
