import React, { useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { api, errMsg, inr } from "../api";
import { Modal, F, useToast, useConfirm } from "../ui";
import { useAuth } from "../App";
import PushNames from "./PushNames";
import { GiveAdvance } from "./Advances";

const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const blank = {
  code: "", name: "", phone: "", email: "", department: "", designation: "", shift_id: "", joining_date: "",
  salary_type: "monthly", earnings: [{ name: "Basic", amount: 0 }], daily_rate: 0, hourly_rate: 0, ot_allowed: true,
  ot_rate_per_hour: 0, pf_enabled: false, esi_enabled: false, pt_amount: 0, other_deductions: [], bank_account: "",
  ifsc: "", uan: "", extra_codes: "", whatsapp_alerts: true, weekly_off: null,
};

export function Avatar({ e, size }) {
  const [bad, setBad] = useState(false);
  const cls = "avatar" + (size === "lg" ? " lg" : "");
  const st = size === "sm" ? { width: 28, height: 28, fontSize: 11 } : null;
  const ini = (e?.name || e?.employee_name || "?").split(" ").map((w) => w[0]).slice(0, 2).join("").toUpperCase();
  const url = e?.photo_url;
  if (url && !bad) return <img className={cls} style={st} src={url} alt="" loading="lazy" onError={() => setBad(true)} />;
  return <span className={cls} style={st}>{ini}</span>;
}

const readImage = (file) => new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = rej; r.readAsDataURL(file); });

export function PhotoBox({ emp, onChange }) {
  const toast = useToast();
  const [busy, setBusy] = useState(false);
  const up = async (file) => {
    if (!file) return;
    setBusy(true);
    try { const r = await api.post(`/employees/${emp.id}/photo`, { data: await readImage(file) }); onChange(r.data.photo_url); toast("Photo saved"); }
    catch (e) { toast(errMsg(e), true); }
    setBusy(false);
  };
  return (
    <div className="row" style={{ alignItems: "flex-end", gap: 14 }}>
      <Avatar e={emp} size="lg" />
      <div className="grid" style={{ gap: 6, justifyItems: "start" }}>
        <label className="btn sm ghost" style={{ cursor: "pointer" }}>{busy ? "Saving…" : emp.photo_url ? "Change photo" : "Upload / take photo"}
          <input type="file" accept="image/*" capture="user" hidden onChange={(e) => up(e.target.files[0])} /></label>
        {emp.photo_url && <button type="button" className="btn sm danger" onClick={async () => { await api.delete(`/employees/${emp.id}/photo`); onChange(null); }}>Remove photo</button>}
        <span className="small muted">Photos from Hikvision terminals are fetched by Sync all.</span>
      </div>
    </div>
  );
}

function ShiftHistory({ emp, shifts, onChanged }) {
  const toast = useToast();
  const [hist, setHist] = useState([]);
  const [f, setF] = useState({ shift_id: shifts[0]?.id || "", from_date: new Date().toISOString().slice(0, 10) });
  const load = () => api.get(`/shifts/history/${emp.id}`).then((r) => setHist(r.data)).catch(() => {});
  useEffect(() => { load(); }, []); // eslint-disable-line
  const name = (id) => (shifts.find((s) => s.id === id) || shifts.find((s) => s.is_default) || {}).name || "Default";
  const change = async () => {
    try { await api.post("/shifts/change", { employee_ids: [emp.id], ...f }); toast(`Shift changed from ${f.from_date}`); load(); onChanged(); }
    catch (e) { toast(errMsg(e), true); }
  };
  return (
    <div className="note" style={{ marginBottom: 18 }}>
      <div className="row" style={{ alignItems: "flex-end" }}>
        <F label="Change shift to"><select value={f.shift_id} onChange={(e) => setF({ ...f, shift_id: e.target.value })}>{shifts.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></F>
        <F label="From date"><input type="date" value={f.from_date} onChange={(e) => setF({ ...f, from_date: e.target.value })} /></F>
        <button type="button" className="btn sm" onClick={change}>Change shift</button>
      </div>
      {hist.length > 0 && <div className="hist" style={{ marginTop: 12 }}>
        {hist.map((h) => <React.Fragment key={h.from}>
          <span className="mono small">{h.from === "1900-01-01" ? "joined" : `from ${h.from}`}</span>
          <span><b>{name(h.shift_id)}</b>{h.note && h.note !== "original" ? <span className="small muted"> · {h.note}</span> : ""}</span>
          {h.from !== "1900-01-01" ? <button type="button" className="btn sm link" onClick={async () => { await api.post(`/shifts/history/${emp.id}/remove`, { from: h.from }); load(); onChanged(); }}>Undo</button> : <span />}
        </React.Fragment>)}
      </div>}
      <div className="small muted" style={{ marginTop: 8 }}>Days before the date keep the old shift. For one-off days use Shift roster.</div>
    </div>
  );
}

function Sheet({ rows, shifts, reload }) {
  const toast = useToast();
  const [pushIds, setPushIds] = useState(null);
  const [d, setD] = useState({});
  const [busy, setBusy] = useState(false);
  const val = (e, k) => (d[e.id] && k in d[e.id] ? d[e.id][k] : k === "amount"
    ? (e.salary_type === "daily" ? e.daily_rate : e.salary_type === "hourly" ? e.hourly_rate : (e.earnings || []).reduce((a, b) => a + Number(b.amount || 0), 0)) || ""
    : e[k] ?? "");
  const set = (e, k) => (ev) => setD({ ...d, [e.id]: { ...(d[e.id] || {}), [k]: ev.target.value } });
  const save = async () => {
    setBusy(true);
    const payload = Object.entries(d).map(([id, ch]) => {
      const e = rows.find((x) => x.id === id);
      const out = { id, ...ch };
      if ("amount" in ch || "salary_type" in ch) {
        const t = ch.salary_type || e.salary_type || "monthly";
        const amt = "amount" in ch ? ch.amount : val(e, "amount");
        delete out.amount;
        out[t === "daily" ? "daily_rate" : t === "hourly" ? "hourly_rate" : "monthly"] = amt;
      }
      return out;
    });
    try {
      const r = await api.put("/employees/bulk", { rows: payload });
      toast(`${r.data.saved} employee(s) saved${r.data.errors.length ? " — " + r.data.errors.join("; ") : ""}`, !!r.data.errors.length);
      const renamed = payload.filter((x) => "name" in x).map((x) => x.id);
      setD({}); reload();
      if (renamed.length) setPushIds(renamed);
    } catch (e) { toast(errMsg(e), true); }
    setBusy(false);
  };
  const n = Object.keys(d).length;
  return (
    <div className="card flush">
      <div className="card-head"><span className="small muted">Fill details for many employees at once — handy right after fetching users from the machine.</span>
        <div className="row">{n > 0 && <button className="btn sm ghost" onClick={() => setD({})}>Undo</button>}
          <button className="btn sm green" disabled={!n || busy} onClick={save}>{busy ? "Saving…" : `Save ${n || ""} change${n === 1 ? "" : "s"}`}</button></div></div>
      <div className="tbl-wrap"><table className="tbl sheet">
        <thead><tr><th /><th>ID</th><th>Name</th><th>Mobile</th><th>Department</th><th>Designation</th><th>Shift</th><th>Pay type</th><th>Salary / rate ₹</th><th>Joining</th></tr></thead>
        <tbody>{rows.map((e) => (
          <tr key={e.id} className={d[e.id] ? "dirty" : ""}>
            <td><Avatar e={e} size="sm" /></td><td className="mono">{e.code}</td>
            <td><input value={val(e, "name")} onChange={set(e, "name")} style={{ minWidth: 150 }} /></td>
            <td><input value={val(e, "phone")} onChange={set(e, "phone")} inputMode="tel" placeholder="10-digit" style={{ minWidth: 120 }} /></td>
            <td><input value={val(e, "department")} onChange={set(e, "department")} /></td>
            <td><input value={val(e, "designation")} onChange={set(e, "designation")} /></td>
            <td><select value={val(e, "shift_id")} onChange={set(e, "shift_id")}><option value="">Default</option>{shifts.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></td>
            <td><select value={val(e, "salary_type") || "monthly"} onChange={set(e, "salary_type")}><option value="monthly">Monthly</option><option value="daily">Daily</option><option value="hourly">Hourly</option></select></td>
            <td><input type="number" value={val(e, "amount")} onChange={set(e, "amount")} style={{ minWidth: 100 }} /></td>
            <td><input type="date" value={val(e, "joining_date")} onChange={set(e, "joining_date")} /></td>
          </tr>))}
          {!rows.length && <tr><td colSpan="10" className="empty">No employees yet.</td></tr>}
        </tbody></table></div>
      {pushIds && <PushNames employeeIds={pushIds} onClose={() => setPushIds(null)} />}
    </div>
  );
}

function Lines({ value, onChange, add }) {
  const rows = value || [];
  const upd = (i, k, v) => onChange(rows.map((r, j) => (j === i ? { ...r, [k]: v } : r)));
  return (
    <div className="grid" style={{ gap: 6 }}>
      {rows.map((r, i) => (
        <div className="row" key={i} style={{ flexWrap: "nowrap" }}>
          <input placeholder="Name" value={r.name} onChange={(e) => upd(i, "name", e.target.value)} />
          <input type="number" placeholder="Amount" value={r.amount} onChange={(e) => upd(i, "amount", e.target.value)} style={{ maxWidth: 140 }} />
          <button type="button" className="btn sm danger" onClick={() => onChange(rows.filter((_, j) => j !== i))}>×</button>
        </div>
      ))}
      <div><button type="button" className="btn sm ghost" onClick={() => onChange([...rows, { name: "", amount: 0 }])}>+ {add}</button></div>
    </div>
  );
}

export default function Employees() {
  const toast = useToast();
  const ask = useConfirm();
  const { me } = useAuth();
  const isOwner = ["owner", "superadmin"].includes(me.user.role);
  const [sel, setSel] = useState({});
  const [hidden, setHidden] = useState([]);
  const [sp] = useSearchParams();
  const [tab, setTab] = useState(sp.get("tab") === "device" ? "device" : "active");
  const [rows, setRows] = useState([]);
  const [devUsers, setDevUsers] = useState([]);
  const [shifts, setShifts] = useState([]);
  const [q, setQ] = useState("");
  const [edit, setEdit] = useState(null);
  const [pick, setPick] = useState({});
  const [csv, setCsv] = useState(false);
  const [push, setPush] = useState(null);
  const [adv, setAdv] = useState(null);

  const load = async () => {
    const [e, d, s] = await Promise.all([
      api.get("/employees?active=" + (tab === "left" ? "0" : "1")), api.get("/device-users"), api.get("/shifts")]);
    setRows(e.data); setDevUsers(d.data); setShifts(s.data); setSel({});
    api.get("/ignored-codes").then((r) => setHidden(r.data)).catch(() => {});
  };
  useEffect(() => { load(); }, [tab]); // eslint-disable-line

  const save = async () => {
    try {
      const body = { ...edit };
      if (edit.id) await api.put("/employees/" + edit.id, body);
      else await api.post("/employees", body);
      toast("Employee saved"); setEdit(null); load();
    } catch (e) { toast(errMsg(e), true); }
  };
  const remove = async (e) => {
    if (!(await ask({ title: `Mark ${e.name} as left?`, message: "They leave the active list. Attendance and salary history stay, and you can rejoin them any time.", okText: "Mark as left" }))) return;
    await api.delete("/employees/" + e.id); toast(`${e.name} marked as left`); load();
  };
  const purge = async (list) => {
    const one = list.length === 1;
    const r = await ask({
      title: one ? `Delete ${list[0].name} permanently?` : `Delete ${list.length} employees permanently?`, danger: true, okText: "Delete permanently",
      message: "Their attendance, leaves, advances and salary slips are deleted. This cannot be undone.",
      options: [
        { key: "punches", label: "Also delete their punch logs", hint: "Deleted punches are not downloaded again from the machine." },
        { key: "ignore", label: "Hide their machine ID on future syncs", default: true, hint: "Otherwise the ID shows up again under “From machines”." },
      ],
    });
    if (!r) return;
    try {
      await api.post("/employees/bulk-delete", { ids: list.map((x) => x.id), permanent: true, punches: r.punches, ignore: r.ignore });
      toast(one ? "Employee deleted" : `${list.length} employees deleted`); setEdit(null); load();
    } catch (e) { toast(errMsg(e), true); }
  };
  const markLeft = async (list) => {
    if (!(await ask({ title: `Mark ${list.length} employees as left?`, okText: "Mark as left", message: "History stays; you can rejoin them later." }))) return;
    await api.post("/employees/bulk-delete", { ids: list.map((x) => x.id) }); toast("Marked as left"); load();
  };
  const removeDev = async () => {
    const codes = Object.keys(pick).filter((k) => pick[k]);
    if (!codes.length) return toast("Select IDs first", true);
    if (!(await ask({ title: `Remove ${codes.length} ID(s) from this list?`, okText: "Remove", danger: true, message: "They stay hidden on future syncs. You can show them again below the list." }))) return;
    await api.post("/device-users/remove", { codes, ignore: true }); setPick({}); toast("Removed"); load();
  };
  const unhide = async (codes) => { const r = await api.post("/ignored-codes/restore", { codes }); toast(r.data.message); load(); };
  const importDev = async () => {
    const codes = Object.keys(pick).filter((k) => pick[k]);
    if (!codes.length) return toast("Select IDs first", true);
    const r = await api.post("/device-users/import", { codes, defaults: {} });
    toast(`${r.data.added} employees added. Open each to set salary & phone.`); setPick({}); setTab("active");
  };
  const uploadCsv = async (file) => {
    const fd = new FormData(); fd.append("file", file);
    try {
      const r = await api.post("/employees/import-csv", fd);
      toast(`${r.data.added} added, ${r.data.updated} updated${r.data.errors.length ? ", " + r.data.errors.length + " errors" : ""}`);
      setCsv(false); load();
    } catch (e) { toast(errMsg(e), true); }
  };
  const set = (k) => (e) => setEdit({ ...edit, [k]: e.target.type === "checkbox" ? e.target.checked : e.target.value });
  const gross = (e) => e.salary_type === "daily" ? `${inr(e.daily_rate)}/day` : e.salary_type === "hourly" ? `${inr(e.hourly_rate)}/hr`
    : inr((e.earnings || []).reduce((a, b) => a + Number(b.amount || 0), 0)) + "/mo";
  const shown = rows.filter((e) => !q || `${e.code} ${e.name} ${e.department} ${e.phone}`.toLowerCase().includes(q.toLowerCase()));
  const selected = shown.filter((e) => sel[e.id]);
  const shiftName = (id) => (shifts.find((s) => s.id === id) || shifts.find((s) => s.is_default) || {}).name;

  return (
    <>
      <div className="page-head">
        <div><h1>Employees</h1><p>The <b>Device ID</b> must match the user ID enrolled on the biometric machine.</p></div>
        <div className="row">
          <button className="btn ghost" onClick={() => setPush({ ids: selected.length ? selected.map((e) => e.id) : undefined })}>Send names to machines</button>
          <button className="btn ghost" onClick={() => setCsv(true)}>Import CSV</button>
          <button className="btn green" onClick={() => setEdit({ ...blank })}>+ Add employee</button>
        </div>
      </div>
      <div className="tabs">
        <button className={tab === "active" ? "on" : ""} onClick={() => setTab("active")}>Active</button>
        <button className={tab === "sheet" ? "on" : ""} onClick={() => setTab("sheet")}>Quick edit</button>
        <button className={tab === "device" ? "on" : ""} onClick={() => setTab("device")}>From machines {devUsers.length ? <span className="chip s-A" style={{ marginLeft: 4 }}>{devUsers.length}</span> : null}</button>
        <button className={tab === "left" ? "on" : ""} onClick={() => setTab("left")}>Left</button>
      </div>

      {tab === "sheet" ? <Sheet rows={rows} shifts={shifts} reload={load} /> : tab !== "device" ? (
        <div className="card flush">
          <div className="card-head"><input placeholder="Search name, ID, department, mobile…" value={q} onChange={(e) => setQ(e.target.value)} style={{ maxWidth: 340 }} /><span className="muted small">{shown.length} employees</span></div>
          {selected.length > 0 && (
            <div className="selbar"><b>{selected.length} selected</b>
              {tab === "active" && <button className="btn sm ghost" onClick={() => setPush({ ids: selected.map((e) => e.id) })}>Send names to machines</button>}
              {tab === "active" && <button className="btn sm ghost" onClick={() => markLeft(selected)}>Mark as left</button>}
              {isOwner && <button className="btn sm danger" onClick={() => purge(selected)}>Delete permanently</button>}
              <button className="btn sm link" onClick={() => setSel({})}>Clear</button></div>)}
          <div className="tbl-wrap"><table className="tbl">
            <thead><tr><th style={{ width: 36 }}><input type="checkbox" checked={shown.length > 0 && shown.every((e) => sel[e.id])} onChange={(e) => setSel(Object.fromEntries(shown.map((x) => [x.id, e.target.checked])))} /></th><th>Device ID</th><th>Name</th><th>Department</th><th>Mobile (WhatsApp)</th><th>Shift</th><th className="num">Salary</th><th /></tr></thead>
            <tbody>{shown.map((e) => (
              <tr key={e.id}>
                <td><input type="checkbox" checked={!!sel[e.id]} onChange={(ev) => setSel({ ...sel, [e.id]: ev.target.checked })} /></td>
                <td className="mono">{e.code}{e.extra_codes?.length ? <span className="muted"> +{e.extra_codes.join(",")}</span> : null}</td>
                <td><div className="who"><Avatar e={e} /><div><b>{e.name}</b><div className="small muted">{e.designation}</div></div></div></td>
                <td>{e.department}</td>
                <td className="mono">{e.phone || <span className="chip s-A">missing</span>}</td>
                <td className="small">{shiftName(e.shift_id)}</td>
                <td className="num">{gross(e)}</td>
                <td className="row" style={{ justifyContent: "flex-end" }}>
                  <button className="btn sm ghost" onClick={() => setEdit({ ...blank, ...e, extra_codes: (e.extra_codes || []).join(", ") })}>Edit</button>
                  {tab === "active" && <button className="btn sm ghost" title="Give salary advance / loan" onClick={() => setAdv(e)}>₹ Advance</button>}
                  {tab === "active" ? <button className="btn sm danger" onClick={() => remove(e)}>Left</button>
                    : <button className="btn sm ghost" onClick={async () => { await api.put("/employees/" + e.id, { active: true, leaving_date: null }); load(); }}>Rejoin</button>}
                  {tab === "left" && isOwner && <button className="btn sm danger" onClick={() => purge([e])}>Delete</button>}
                </td>
              </tr>))}
              {!shown.length && <tr><td colSpan="8" className="empty">No employees. Add manually, import CSV, or pick from machine users.</td></tr>}
            </tbody></table></div>
        </div>
      ) : (
        <div className="card flush">
          <div className="card-head">
            <span className="muted small">IDs found on the machines (or punching) that are not linked to any employee.</span>
            <div className="row"><button className="btn sm danger" onClick={removeDev}>Remove selected</button>
              <button className="btn green sm" onClick={importDev}>Add selected as employees</button></div>
          </div>
          <table className="tbl"><thead><tr><th style={{ width: 40 }}><input type="checkbox" onChange={(e) => setPick(Object.fromEntries(devUsers.map((u) => [u.user_code, e.target.checked])))} /></th><th>Machine ID</th><th>Name on machine</th><th>Device</th><th>Last punch</th></tr></thead>
            <tbody>{devUsers.map((u) => (
              <tr key={u.user_code}><td><input type="checkbox" checked={!!pick[u.user_code]} onChange={(e) => setPick({ ...pick, [u.user_code]: e.target.checked })} /></td>
                <td className="mono">{u.user_code}</td><td><div className="who"><Avatar e={u} size="sm" />{u.name || "—"}</div></td><td>{u.device_name}</td><td className="mono small">{u.last_punch || "—"}</td></tr>))}
              {!devUsers.length && <tr><td colSpan="5" className="empty">Nothing pending. Use “Sync all” to read user lists from the machines.</td></tr>}
            </tbody></table>
          {hidden.length > 0 && (
            <div className="selbar" style={{ background: "#f8fafc", borderTop: "1px solid var(--line)", borderBottom: 0 }}>
              <span className="muted">Hidden IDs:</span>
              {hidden.map((c) => <button key={c} className="btn sm ghost" title="Show again" onClick={() => unhide([c])}><span className="mono">{c}</span> ↺</button>)}
              <button className="btn sm link" onClick={() => unhide(hidden)}>Show all again</button>
            </div>)}
        </div>
      )}

      {push && <PushNames employeeIds={push.ids} onClose={() => setPush(null)} />}
      {adv && <GiveAdvance employee={adv} onClose={() => setAdv(null)} />}
      {csv && (
        <Modal title="Import employees from CSV" onClose={() => setCsv(false)}>
          <p>Columns (first row = headers): <span className="mono">code, name, phone, department, designation, salary_type, salary, daily_rate, joining_date</span></p>
          <p className="muted small">Existing device IDs are updated, new ones added. Dates as YYYY-MM-DD. salary_type = monthly / daily / hourly.</p>
          <input type="file" accept=".csv" onChange={(e) => e.target.files[0] && uploadCsv(e.target.files[0])} />
        </Modal>
      )}

      {edit && (
        <Modal wide title={edit.id ? `Edit — ${edit.name}` : "Add employee"} onClose={() => setEdit(null)}
          footer={<>{edit.id && isOwner && <button className="btn danger" style={{ marginRight: "auto" }} onClick={() => purge([edit])}>Delete permanently</button>}
            <button className="btn ghost" onClick={() => setEdit(null)}>Cancel</button><button className="btn green" onClick={save}>Save employee</button></>}>
          {edit.id && <div style={{ marginBottom: 18 }}><PhotoBox emp={edit} onChange={(u) => { setEdit({ ...edit, photo_url: u }); load(); }} /></div>}
          <h3>Basic</h3>
          <div className="grid g3" style={{ marginBottom: 18 }}>
            <F label="Device user ID *"><input value={edit.code} onChange={set("code")} placeholder="e.g. 101" /></F>
            <F label="Full name *"><input value={edit.name} onChange={set("name")} /></F>
            <F label="Mobile (WhatsApp)"><input value={edit.phone} onChange={set("phone")} placeholder="10-digit" /></F>
            <F label="Department"><input value={edit.department} onChange={set("department")} /></F>
            <F label="Designation"><input value={edit.designation} onChange={set("designation")} /></F>
            <F label="Joining date"><input type="date" value={edit.joining_date || ""} onChange={set("joining_date")} /></F>
            <F label={edit.id ? "Shift (change applies from today)" : "Shift"}><select value={edit.shift_id || ""} onChange={set("shift_id")}><option value="">Default shift</option>{shifts.map((s) => <option key={s.id} value={s.id}>{s.name} ({s.start}–{s.end})</option>)}</select></F>
            <F label="Other machine IDs (comma)"><input value={edit.extra_codes} onChange={set("extra_codes")} placeholder="if ID differs on 2nd machine" /></F>
            <F label="Email"><input value={edit.email || ""} onChange={set("email")} /></F>
          </div>
          {edit.id && <><h3>Shift changes</h3><ShiftHistory emp={edit} shifts={shifts} onChanged={async () => { const r = await api.get("/employees"); const x = r.data.find((y) => y.id === edit.id); if (x) setEdit({ ...edit, shift_id: x.shift_id }); }} /></>}
          <div className="row" style={{ marginBottom: 18, gap: 18 }}>
            <label className="check"><input type="checkbox" checked={edit.whatsapp_alerts !== false} onChange={set("whatsapp_alerts")} /> Send WhatsApp alerts</label>
            <label className="check"><input type="checkbox" checked={edit.weekly_off != null} onChange={(e) => setEdit({ ...edit, weekly_off: e.target.checked ? [6] : null })} /> Own weekly off (instead of shift's)</label>
            {edit.weekly_off != null && DAYS.map((d, i) => (
              <label className="check" key={d}><input type="checkbox" checked={edit.weekly_off.includes(i)}
                onChange={(e) => setEdit({ ...edit, weekly_off: e.target.checked ? [...edit.weekly_off, i] : edit.weekly_off.filter((x) => x !== i) })} />{d}</label>))}
          </div>
          <h3>Salary</h3>
          <div className="seg" style={{ marginBottom: 12 }}>
            {["monthly", "daily", "hourly"].map((t) => <button type="button" key={t} className={edit.salary_type === t ? "on" : ""} onClick={() => setEdit({ ...edit, salary_type: t })}>{t[0].toUpperCase() + t.slice(1)}</button>)}
          </div>
          <div className="grid g2" style={{ marginBottom: 18 }}>
            <div>
              {edit.salary_type === "monthly" && <><div className="small muted" style={{ marginBottom: 6 }}>Monthly earnings (full month)</div>
                <Lines value={edit.earnings} onChange={(v) => setEdit({ ...edit, earnings: v })} add="Add allowance" /></>}
              {edit.salary_type === "daily" && <F label="Wage per day (₹)"><input type="number" value={edit.daily_rate} onChange={set("daily_rate")} /></F>}
              {edit.salary_type === "hourly" && <F label="Rate per hour (₹)"><input type="number" value={edit.hourly_rate} onChange={set("hourly_rate")} /></F>}
              <div className="row" style={{ marginTop: 12 }}>
                <label className="check"><input type="checkbox" checked={edit.ot_allowed !== false} onChange={set("ot_allowed")} /> Overtime paid</label>
                {edit.ot_allowed !== false && <input type="number" style={{ maxWidth: 170 }} placeholder="OT ₹/hr (blank = auto)" value={edit.ot_rate_per_hour || ""} onChange={set("ot_rate_per_hour")} />}
              </div>
            </div>
            <div>
              <div className="small muted" style={{ marginBottom: 6 }}>Deductions</div>
              <div className="row" style={{ marginBottom: 8 }}>
                <label className="check"><input type="checkbox" checked={!!edit.pf_enabled} onChange={set("pf_enabled")} /> PF</label>
                <label className="check"><input type="checkbox" checked={!!edit.esi_enabled} onChange={set("esi_enabled")} /> ESI</label>
                <input type="number" style={{ maxWidth: 160 }} placeholder="Prof. tax ₹" value={edit.pt_amount || ""} onChange={set("pt_amount")} />
              </div>
              <Lines value={edit.other_deductions} onChange={(v) => setEdit({ ...edit, other_deductions: v })} add="Fixed deduction" />
            </div>
          </div>
          <h3>Bank (for salary sheet)</h3>
          <div className="grid g3">
            <F label="Bank A/c no."><input value={edit.bank_account || ""} onChange={set("bank_account")} /></F>
            <F label="IFSC"><input value={edit.ifsc || ""} onChange={set("ifsc")} /></F>
            <F label="UAN / PF no."><input value={edit.uan || ""} onChange={set("uan")} /></F>
            <F label="ESI no."><input value={edit.esi_no || ""} onChange={set("esi_no")} /></F>
            <F label="PAN"><input value={edit.pan || ""} onChange={(ev) => setEdit({ ...edit, pan: ev.target.value.toUpperCase() })} /></F>
          </div>
        </Modal>
      )}
    </>
  );
}
