import axios from "axios";

const BUILD_DEMO = process.env.REACT_APP_DEMO === "1";
// LICENSE_DEMO: this computer has no valid licence key -> same demo panel, loaded at runtime (see index.js)
export const LICENSE_DEMO = !BUILD_DEMO && !!window.__HAYAT_DEMO_MOD;
export const DEMO = BUILD_DEMO || LICENSE_DEMO;
export const LICENSE = window.__HAYAT_LICENSE || null;
export const UNLICENSED = !DEMO && !!LICENSE && LICENSE.required && !LICENSE.licensed;
export const setDemo = (on) => { try { if (on) sessionStorage.setItem("hayat_demo", "1"); else sessionStorage.removeItem("hayat_demo"); } catch { /* ignore */ } window.location.href = "/"; };
const demo = BUILD_DEMO ? require("./demo") : window.__HAYAT_DEMO_MOD || null;

// localStorage can be blocked (private windows, embedded viewers) — never let it crash the app
const mem = {};
export const store = LICENSE_DEMO ? {
  // demo on an unlicensed computer: never touch the real login saved in this browser
  get: (k) => mem[k] ?? null, set: (k, v) => { mem[k] = v; }, del: (k) => { delete mem[k]; },
} : {
  get: (k) => { try { return localStorage.getItem(k); } catch { return mem[k] ?? null; } },
  set: (k, v) => { try { localStorage.setItem(k, v); } catch { mem[k] = v; } },
  del: (k) => { try { localStorage.removeItem(k); } catch { delete mem[k]; } },
};
if (DEMO) store.set("hrms_token", "demo");

export const BASE = (process.env.REACT_APP_BACKEND_URL || "").replace(/\/$/, "");
// plain client that always talks to the real server (licence screens work even in the demo panel)
export const realApi = axios.create({ baseURL: BASE + "/api" });
realApi.interceptors.request.use((cfg) => {
  if (!LICENSE_DEMO) { const t = store.get("hrms_token"); if (t) cfg.headers.Authorization = "Bearer " + t; }
  return cfg;
});
export const api = axios.create({ baseURL: BASE + "/api", ...(DEMO ? { adapter: demo.demoAdapter, baseURL: "" } : {}) });

api.interceptors.request.use((cfg) => {
  const t = store.get("hrms_token");
  if (t) cfg.headers.Authorization = "Bearer " + t;
  const cid = store.get("hrms_cid");
  if (cid) cfg.headers["X-Company-Id"] = cid;
  return cfg;
});
api.interceptors.response.use(
  (r) => r,
  (e) => {
    if (!DEMO && !UNLICENSED && e.response && e.response.status === 402 && e.response.data?.license_required) {
      window.location.reload(); // licence ended while the page was open -> boot again into the demo/activation screen
    }
    if (!DEMO && e.response && e.response.status === 401 && !e.config.url.includes("/auth/login")) {
      store.del("hrms_token");
      window.location.href = "/login";
    }
    return Promise.reject(e);
  }
);

export const errMsg = (e) => {
  const d = e?.response?.data?.detail;
  if (typeof d === "string") return d;
  if (Array.isArray(d)) return d.map((x) => x.msg).join(", ");
  return e?.message || "Something went wrong";
};

export async function download(path, filename) {
  if (DEMO) return demo.demoDownload(path, filename);
  const r = await api.get(path, { responseType: "blob" });
  const url = URL.createObjectURL(r.data);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

export async function openPdf(path) {
  if (DEMO) return demo.demoPdf(path);
  const w = window.open("", "_blank");
  const r = await api.get(path, { responseType: "blob" });
  const url = URL.createObjectURL(new Blob([r.data], { type: "application/pdf" }));
  if (w) w.location.href = url;
  else window.location.href = url;
}

export const today = () => {
  if (DEMO) return demo.DEMO_TODAY;
  const d = new Date();
  return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
};
export const thisMonth = () => today().slice(0, 7);
export const prevMonth = () => {
  const d = new Date(today());
  d.setDate(1);
  d.setMonth(d.getMonth() - 1);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
};
export const inr = (n) => "₹" + Number(n || 0).toLocaleString("en-IN", { maximumFractionDigits: 2 });
export const hmm = (m) => { m = Math.round(m || 0); return `${Math.floor(m / 60)}:${String(m % 60).padStart(2, "0")}`; };
export const ago = (iso) => {
  if (!iso) return "never";
  const s = (Date.now() - new Date(iso).getTime()) / 1000;
  if (s < 60) return "just now";
  if (s < 3600) return Math.floor(s / 60) + " min ago";
  if (s < 86400) return Math.floor(s / 3600) + " hr ago";
  return Math.floor(s / 86400) + " days ago";
};
