import React, { useEffect, useState } from "react";
import { api, errMsg, thisMonth, today, inr } from "../api";
import { F, useToast } from "../ui";
import { GiveAdvance, EditAdvance, ExportButtons } from "./Advances";

export default function Leaves() {
  const toast = useToast();
  const [tab, setTab] = useState("leave");
  const [emps, setEmps] = useState([]);
  const [month, setMonth] = useState(thisMonth());
  const [leaves, setLeaves] = useState([]);
  const [hols, setHols] = useState([]);
  const [advs, setAdvs] = useState([]);
  const [lf, setLf] = useState({ employee_id: "", from_date: today(), to_date: today(), type: "CL", paid: true, reason: "" });
  const [hf, setHf] = useState({ date: "", name: "" });
  const [give, setGive] = useState(false);
  const [editAdv, setEditAdv] = useState(null);
  const year = month.slice(0, 4);
  const load = async () => {
    const [e, l, h, a] = await Promise.all([api.get("/employees"), api.get("/leaves?month=" + month), api.get("/holidays?year=" + year), api.get("/advances")]);
    setEmps(e.data); setLeaves(l.data); setHols(h.data); setAdvs(a.data);
  };
  useEffect(() => { load(); }, [month]); // eslint-disable-line
  const go = async (fn, msg) => { try { await fn(); toast(msg); load(); } catch (e) { toast(errMsg(e), true); } };
  const EmpSel = ({ v, on }) => <select value={v} onChange={(e) => on(e.target.value)}><option value="">Select employee</option>{emps.map((e) => <option key={e.id} value={e.id}>{e.code} — {e.name}</option>)}</select>;
  return (
    <>
      <div className="page-head"><div><h1>Leave · Holidays · Advance</h1></div>
        {tab !== "adv" && <input type="month" value={month} onChange={(e) => setMonth(e.target.value)} style={{ width: 170 }} />}</div>
      <div className="tabs">
        {[["leave", "Leaves"], ["hol", "Holidays " + year], ["adv", "Salary advances"]].map(([k, l]) => <button key={k} className={tab === k ? "on" : ""} onClick={() => setTab(k)}>{l}</button>)}
      </div>
      {tab === "leave" && (
        <div className="grid g3">
          <div className="card">
            <h2>Mark leave</h2>
            <div className="grid">
              <F label="Employee"><EmpSel v={lf.employee_id} on={(v) => setLf({ ...lf, employee_id: v })} /></F>
              <div className="grid g2"><F label="From"><input type="date" value={lf.from_date} onChange={(e) => setLf({ ...lf, from_date: e.target.value })} /></F>
                <F label="To"><input type="date" value={lf.to_date} onChange={(e) => setLf({ ...lf, to_date: e.target.value })} /></F></div>
              <F label="Type"><select value={lf.type} onChange={(e) => setLf({ ...lf, type: e.target.value, paid: e.target.value !== "LWP" })}>
                <option value="CL">Casual leave</option><option value="SL">Sick leave</option><option value="PL">Privilege / earned leave</option><option value="LWP">Leave without pay</option></select></F>
              <label className="check"><input type="checkbox" checked={lf.paid} onChange={(e) => setLf({ ...lf, paid: e.target.checked })} /> Paid leave</label>
              <F label="Reason"><input value={lf.reason} onChange={(e) => setLf({ ...lf, reason: e.target.value })} /></F>
              <button className="btn green" onClick={() => go(() => api.post("/leaves", lf), "Leave saved")}>Save leave</button>
              <p className="small muted">If the employee still punches on that day, the punches win and the day counts as worked.</p>
            </div>
          </div>
          <div className="card flush" style={{ gridColumn: "span 2" }}>
            <table className="tbl"><thead><tr><th>Date</th><th>Employee</th><th>Type</th><th>Paid</th><th>Reason</th><th /></tr></thead>
              <tbody>{leaves.map((l) => (
                <tr key={l.id}><td className="mono">{l.date}</td><td>{l.employee_name}</td><td>{l.type}</td><td>{l.paid ? "Yes" : "No"}</td><td className="small">{l.reason}</td>
                  <td><button className="btn sm danger" onClick={() => go(() => api.delete("/leaves/" + l.id), "Removed")}>×</button></td></tr>))}
                {!leaves.length && <tr><td colSpan="6" className="empty">No leaves this month.</td></tr>}</tbody></table>
          </div>
        </div>
      )}
      {tab === "hol" && (
        <div className="grid g3">
          <div className="card"><h2>Add holiday</h2>
            <div className="grid"><F label="Date"><input type="date" value={hf.date} onChange={(e) => setHf({ ...hf, date: e.target.value })} /></F>
              <F label="Name"><input value={hf.name} onChange={(e) => setHf({ ...hf, name: e.target.value })} placeholder="Diwali" /></F>
              <button className="btn green" onClick={() => go(() => api.post("/holidays", hf), "Holiday added")}>Add holiday</button></div></div>
          <div className="card flush" style={{ gridColumn: "span 2" }}>
            <table className="tbl"><thead><tr><th>Date</th><th>Day</th><th>Holiday</th><th /></tr></thead>
              <tbody>{hols.map((h) => (<tr key={h.id}><td className="mono">{h.date}</td><td>{new Date(h.date).toLocaleDateString("en-IN", { weekday: "long" })}</td><td style={{ fontWeight: 600 }}>{h.name}</td>
                <td><button className="btn sm danger" onClick={() => go(() => api.delete("/holidays/" + h.id), "Removed")}>×</button></td></tr>))}
                {!hols.length && <tr><td colSpan="4" className="empty">No holidays for {year}.</td></tr>}</tbody></table>
          </div>
        </div>
      )}
      {tab === "adv" && (
        <div className="card flush">
          <div className="card-head">
            <div className="row">
              <button className="btn green sm" onClick={() => setGive(true)}>+ Give advance</button>
              <span className="small muted">Open balance <b>{inr(advs.reduce((s, a) => s + (a.balance || 0), 0))}</b> · {advs.filter((a) => a.balance > 0).length} open</span>
            </div>
            <ExportButtons path="/reports/advances" name="Advances" disabled={!advs.length} />
          </div>
          <div className="tbl-wrap"><table className="tbl"><thead><tr><th>Date</th><th>Employee</th><th className="num">Amount</th><th>Recovery</th><th className="num">Recovered</th><th className="num">Balance</th><th>Note</th><th /></tr></thead>
            <tbody>{advs.map((a) => (<tr key={a.id}><td className="mono" style={{ whiteSpace: "nowrap" }}>{a.date}</td><td style={{ fontWeight: 600 }}>{a.employee_name} <span className="mono muted">{a.emp_code}</span></td><td className="num">{inr(a.amount)}</td>
              <td className="small">{a.auto && a.installment > 0 ? `${inr(a.installment)} / month (auto)` : <span className="chip s-HD">ask every month</span>}</td>
              <td className="num">{inr(a.amount - a.balance)}</td>
              <td className="num" style={{ fontWeight: 700 }}>{a.balance > 0 ? inr(a.balance) : <span className="chip s-P">cleared</span>}</td><td className="small">{a.note}</td>
              <td className="row" style={{ justifyContent: "flex-end", flexWrap: "nowrap" }}>
                <button className="btn sm ghost" onClick={() => setEditAdv(a)}>Edit</button>
                {!a.recoveries?.length && <button className="btn sm danger" onClick={() => go(() => api.delete("/advances/" + a.id), "Removed")}>×</button>}</td></tr>))}
              {!advs.length && <tr><td colSpan="8" className="empty">No advances. Use “Give advance”.</td></tr>}</tbody></table></div>
          <p className="small muted" style={{ padding: "0 16px 14px" }}>Recovery is decided at salary time (Payroll → Adjust or “Advance cuts”) and posted when the month is finalised.</p>
        </div>
      )}
      {give && <GiveAdvance onClose={() => setGive(false)} onDone={load} />}
      {editAdv && <EditAdvance adv={editAdv} onClose={() => setEditAdv(null)} onDone={load} />}
    </>
  );
}
