import React, { useEffect, useState } from "react";
import { api, errMsg, ago } from "../api";
import { Modal, F, useToast, Copy, useConfirm } from "../ui";
import PushNames from "./PushNames";

const MODES = {
  agent: { t: "LAN agent (recommended)", d: "A small program on any PC at the site reads the machine over LAN (192.168.x.x) and uploads to this server. No static IP or port forwarding." },
  adms: { t: "eSSL ADMS / Cloud push", d: "The eSSL/ZKTeco machine itself sends every punch to this server over the internet (machine needs ADMS / Cloud Server option)." },
  hik_push: { t: "Hikvision HTTP push", d: "The Hikvision terminal posts every face/finger/card event to this server (HTTP Listening)." },
  direct: { t: "Direct pull — static IP / local", d: "The app connects to the machine itself: its public static IP (router port-forward 4370 for eSSL / 80 for Hikvision), or its LAN IP when the app is installed on a PC in the same office." },
};
const blank = { name: "", brand: "essl", mode: "agent", ip: "", port: "", comm_key: 0, username: "admin", password: "", serial: "", location: "", pull_interval_minutes: 5, initial_days: 45, enabled: true };

function Setup({ d, base }) {
  const host = base.replace(/^https?:\/\//, "");
  if (d.mode === "adms") return (
    <div className="grid" style={{ gap: 8 }}>
      <div className="small">On the machine: <b>Menu → Comm. → Cloud Server Setting</b> (some models: <b>ADMS</b>)</div>
      <div className="kv"><dt>Server address</dt><dd className="mono">{host}</dd><dt>Server port</dt><dd className="mono">{base.startsWith("https") ? "443 (HTTPS ON)" : "80"}</dd>
        <dt>Enable domain name</dt><dd>ON</dd><dt>Serial no. here</dt><dd className="mono">{d.serial}</dd></div>
      <div className="small muted">The machine calls <span className="mono">{base}/iclock/cdata</span>. Hosts that route only /api to the backend (e.g. Emergent) need the agent mode or a proxy rule for /iclock.</div>
    </div>);
  if (d.mode === "hik_push") return (
    <div className="grid" style={{ gap: 8 }}>
      <div className="small">Hikvision web page: <b>Configuration → Network → Advanced → HTTP Listening</b> (or Event / Alarm server)</div>
      <div className="kv"><dt>Destination IP/host</dt><dd className="mono">{host}</dd><dt>Port</dt><dd className="mono">{base.startsWith("https") ? 443 : 80}</dd><dt>Protocol</dt><dd>{base.startsWith("https") ? "HTTPS" : "HTTP"}</dd></div>
      <div className="small">URL</div><Copy text={`/api/push/hikvision/${d.push_token}`} />
    </div>);
  if (d.mode === "agent") return <div className="small">Read by the Hayat Sync Agent on the site PC (see “LAN agent” box above). Machine at <span className="mono">{d.ip}:{d.port}</span>.</div>;
  return <div className="small">Server connects to <span className="mono">{d.ip}:{d.port}</span> every {d.pull_interval_minutes || 5} min. Forward this port on the site router to the machine's LAN IP.</div>;
}

export default function Devices() {
  const toast = useToast();
  const ask = useConfirm();
  const [data, setData] = useState({ devices: [], server_base: "" });
  const [edit, setEdit] = useState(null);
  const [busy, setBusy] = useState("");
  const [show, setShow] = useState(null);
  const [push, setPush] = useState(null);
  const [scan, setScan] = useState(null);
  const runScan = async () => {
    setScan({ busy: true, found: [] });
    try { const r = await api.post("/devices/discover", { comm_key: edit?.comm_key || 0 }); setScan({ ...r.data, busy: false }); }
    catch (e) { setScan({ busy: false, found: [], message: errMsg(e) }); }
  };
  const load = () => api.get("/devices").then((r) => setData(r.data));
  useEffect(() => { load(); const t = setInterval(load, 20000); return () => clearInterval(t); }, []);

  const save = async () => {
    try {
      if (edit.id) await api.put("/devices/" + edit.id, edit);
      else await api.post("/devices", edit);
      toast("Device saved"); setEdit(null); load();
    } catch (e) { toast(errMsg(e), true); }
  };
  const act = async (d, what, body) => {
    setBusy(d.id + what);
    try {
      const r = await api.post(`/devices/${d.id}/${what}`, body || {});
      const m = r.data.message || (r.data.ok ? `Done — ${r.data.new_punches ?? 0} new punches, ${r.data.users ?? 0} users` : r.data.error);
      toast(m + (r.data.device_time ? ` · device time ${r.data.device_time}` : "") + (r.data.users != null && what === "test" ? ` · ${r.data.users} users, ${r.data.records} logs` : ""), !r.data.ok);
      load();
    } catch (e) { toast(errMsg(e), true); }
    setBusy("");
  };
  const del = async (d) => {
    const r = await ask({ title: `Remove ${d.name}?`, danger: true, okText: "Remove device", message: "The app stops reading this machine. Nothing is deleted on the machine itself.",
      options: [{ key: "punches", label: `Also delete its ${d.total_punches || 0} punch logs`, hint: "Attendance for those days is recalculated." }] });
    if (!r) return;
    try { await api.delete(`/devices/${d.id}${r.punches ? "?punches=1" : ""}`); toast("Device removed"); load(); } catch (e) { toast(errMsg(e), true); }
  };
  const set = (k) => (e) => setEdit({ ...edit, [k]: e.target.type === "checkbox" ? e.target.checked : e.target.value });
  const agentDevs = data.devices.filter((d) => d.mode === "agent");

  return (
    <>
      <div className="page-head">
        <div><h1>Biometric devices</h1><p>eSSL · ZKTeco · Identix · Realtime (ZK protocol) and Hikvision face/finger terminals.</p></div>
        <button className="btn green" onClick={() => setEdit({ ...blank })}>+ Add device</button>
      </div>

      {(agentDevs.length > 0 || data.agent_key) && (
        <div className="card" style={{ marginBottom: 14 }}>
          <div className="row" style={{ alignItems: "flex-start" }}>
            <div style={{ flex: 1, minWidth: 260 }}>
              <h2>LAN agent</h2>
              <p className="small muted">Install the Hayat Sync Agent on one always-on PC at the site (same network as the machines). Put these two values in its <span className="mono">config.json</span>, then run <span className="mono">install_autostart.bat</span> as Administrator.</p>
              <p className="small">Quick device test from that PC: <span className="mono">test_device.bat 192.168.10.11</span></p>
            </div>
            <div style={{ flex: 1, minWidth: 300 }} className="grid">
              <div className="small muted">server_url</div><Copy text={data.server_base} />
              {data.agent_key && <><div className="small muted">agent_key</div><Copy text={data.agent_key} /></>}
            </div>
          </div>
        </div>
      )}

      <div className="grid g2">
        {data.devices.map((d) => (
          <div className="card" key={d.id}>
            <div className="row" style={{ marginBottom: 10 }}>
              <span className={"dot " + (d.status || "new")} />
              <div style={{ flex: 1 }}><b style={{ fontSize: 15 }}>{d.name}</b><div className="small muted">{d.brand === "hikvision" ? "Hikvision" : "eSSL / ZKTeco"} · {MODES[d.mode]?.t}</div></div>
              <span className="small muted">{d.status === "online" ? "online" : d.status === "new" ? "waiting" : d.status} · {ago(d.last_seen)}</span>
            </div>
            <div className="kv" style={{ marginBottom: 10 }}>
              {d.ip && <><dt>IP / port</dt><dd className="mono">{d.ip}:{d.port}</dd></>}
              {d.hw_serial && <><dt>Machine serial</dt><dd className="mono">{d.hw_serial}</dd></>}
              {d.serial && <><dt>Serial (SN)</dt><dd className="mono">{d.serial}</dd></>}
              <dt>Last punch</dt><dd className="mono">{d.last_punch_at || "—"}</dd>
              <dt>Punches received</dt><dd>{d.total_punches || 0}</dd>
              {d.device_users != null && <><dt>Users on machine</dt><dd>{d.device_users}</dd></>}
            </div>
            {d.sync_error && <div className="note warn small" style={{ marginBottom: 10 }}>{d.sync_error}</div>}
            {d.ip_changed && <div className="note small" style={{ marginBottom: 10 }}>Machine moved from {d.ip_changed.from} to {d.ip_changed.to} — found and updated automatically. Tip: set a fixed IP on the machine.</div>}
            {d.push_result && <div className={"note small " + (d.push_result.error ? "warn" : "ok")} style={{ marginBottom: 10 }}>
              {d.push_result.error ? `Names not written: ${d.push_result.error}` : `Names written: ${(d.push_result.updated || []).length} renamed${(d.push_result.missing || []).length ? `, ${d.push_result.missing.length} IDs not on this machine` : ""}`}</div>}
            {show === d.id && <div className="note" style={{ marginBottom: 10 }}><Setup d={d} base={data.server_base} /></div>}
            <div className="row">
              <button className="btn sm ghost" onClick={() => setShow(show === d.id ? null : d.id)}>{show === d.id ? "Hide setup" : "Setup"}</button>
              {d.mode === "direct" && <button className="btn sm ghost" disabled={!!busy} onClick={() => act(d, "test")}>{busy === d.id + "test" ? "Testing…" : "Test"}</button>}
              {d.mode !== "hik_push" && <button className="btn sm ghost" disabled={!!busy} onClick={() => act(d, "sync")}>{busy === d.id + "sync" ? "Syncing…" : "Sync now"}</button>}
              {d.mode !== "hik_push" && <button className="btn sm ghost" disabled={!!busy} onClick={() => { act(d, "sync", { days_back: 31 }); }}>Last 31 days</button>}
              {d.mode !== "hik_push" && <button className="btn sm ghost" disabled={!!busy} onClick={() => act(d, "fetch-users")}>Users</button>}
              {d.mode !== "hik_push" && <button className="btn sm ghost" onClick={() => setPush(d.id)}>Send names</button>}
              <div className="spacer" />
              <button className="btn sm ghost" onClick={() => setEdit({ ...blank, ...d, password: "" })}>Edit</button>
              <button className="btn sm danger" onClick={() => del(d)}>Remove</button>
            </div>
          </div>
        ))}
        {!data.devices.length && <div className="card empty" style={{ gridColumn: "1/-1" }}>No devices yet. Click “Add device”.</div>}
      </div>

      {push && <PushNames deviceIds={[push]} onClose={() => { setPush(null); load(); }} />}
      {edit && (
        <Modal wide title={edit.id ? "Edit device" : "Add biometric device"} onClose={() => { setEdit(null); setScan(null); }}
          footer={<><button className="btn ghost" onClick={() => setEdit(null)}>Cancel</button><button className="btn green" onClick={save}>Save device</button></>}>
          <div className="grid g2" style={{ marginBottom: 16 }}>
            <F label="Device name"><input value={edit.name} onChange={set("name")} placeholder="Main gate" /></F>
            <F label="Brand"><select value={edit.brand} onChange={(e) => setEdit({ ...edit, brand: e.target.value, port: "", mode: e.target.value === "essl" && edit.mode === "hik_push" ? "agent" : e.target.value === "hikvision" && edit.mode === "adms" ? "agent" : edit.mode })}>
              <option value="essl">eSSL / ZKTeco / Identix (ZK protocol)</option><option value="hikvision">Hikvision access terminal</option></select></F>
          </div>
          <div className="small muted" style={{ marginBottom: 6, fontWeight: 600 }}>How does it connect?</div>
          <div className="grid g2" style={{ marginBottom: 16 }}>
            {Object.entries(MODES).filter(([k]) => !(k === "adms" && edit.brand === "hikvision") && !(k === "hik_push" && edit.brand === "essl")).map(([k, m]) => (
              <label key={k} className="card" style={{ cursor: "pointer", padding: 12, borderColor: edit.mode === k ? "var(--mint)" : undefined, boxShadow: edit.mode === k ? "0 0 0 3px rgba(16,185,129,.15)" : undefined }}>
                <div className="row" style={{ flexWrap: "nowrap" }}><input type="radio" checked={edit.mode === k} onChange={() => setEdit({ ...edit, mode: k })} style={{ width: 16 }} /><b>{m.t}</b></div>
                <div className="small muted" style={{ marginTop: 4 }}>{m.d}</div>
              </label>))}
          </div>
          <div className="grid g3">
            {["agent", "direct"].includes(edit.mode) && <>
              <F label={edit.mode === "direct" ? "IP (static IP, or LAN IP when installed locally)" : "LAN IP of machine"}>
                <div className="row" style={{ flexWrap: "nowrap" }}><input value={edit.ip} onChange={set("ip")} placeholder="192.168.10.3" />
                  {edit.brand === "essl" && <button type="button" className="btn ghost" onClick={runScan} title="Search this network for eSSL machines">Find</button>}</div></F>
              <F label="Port"><input type="number" value={edit.port} onChange={set("port")} placeholder={edit.brand === "hikvision" ? "80" : "4370"} /></F>
            </>}
            {edit.brand === "essl" && ["agent", "direct"].includes(edit.mode) && <F label="Comm Key (0 if not set)"><input type="number" value={edit.comm_key} onChange={set("comm_key")} /></F>}
            {edit.brand === "hikvision" && ["agent", "direct"].includes(edit.mode) && <>
              <F label="Device username"><input value={edit.username} onChange={set("username")} /></F>
              <F label={edit.has_password ? "Password (blank = keep)" : "Device password"}><input type="password" value={edit.password} onChange={set("password")} /></F>
            </>}
            {edit.mode === "adms" && <F label="Machine serial number (SN) *"><input value={edit.serial} onChange={set("serial")} placeholder="Menu → System info → Device info" /></F>}
            {edit.mode === "direct" && <F label="Pull every (minutes)"><input type="number" value={edit.pull_interval_minutes} onChange={set("pull_interval_minutes")} /></F>}
            {["agent", "direct"].includes(edit.mode) && <F label="First sync — days of history (3650 = all)"><input type="number" value={edit.initial_days} onChange={set("initial_days")} /></F>}
            <F label="Location"><input value={edit.location || ""} onChange={set("location")} /></F>
          </div>
          {scan && (
            <div className="note" style={{ marginTop: 14 }}>
              {scan.busy ? "Searching the network for eSSL / ZKTeco machines (about 10 seconds)…" : <>
                <b>{scan.found.length ? `Found ${scan.found.length} machine(s)` : "No machines found"}</b>{scan.scanned?.length ? <span className="small muted"> · searched {scan.scanned.join(", ")}</span> : null}
                {scan.message && <div className="small" style={{ marginTop: 4 }}>{scan.message}</div>}
                {scan.found.map((f) => (
                  <div className="res-row" key={f.ip}>
                    <span className="mono" style={{ minWidth: 120 }}>{f.ip}</span>
                    <span className="small" style={{ flex: 1 }}>{f.needs_key ? "Needs a Comm Key — enter it above and search again" : `Serial ${f.serial || "?"} · ${f.users ?? "?"} users · ${f.protocol}`}{f.added_as ? <b> · already added as “{f.added_as}”</b> : ""}</span>
                    <button type="button" className="btn sm" onClick={() => { setEdit({ ...edit, ip: f.ip, port: f.port }); setScan(null); }}>Use</button>
                  </div>))}
                {!scan.found.length && !scan.message && <div className="small muted">Check the machine is on and on the same network. When the app runs online (Vercel), search from the shop PC with find_devices.bat in the agent folder.</div>}
              </>}
            </div>
          )}
          <label className="check" style={{ marginTop: 14 }}><input type="checkbox" checked={edit.enabled !== false} onChange={set("enabled")} /> Enabled</label>
        </Modal>
      )}
    </>
  );
}
