import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api, errMsg, ago, LICENSE } from "../api";
import { Modal, F, useToast, useConfirm } from "../ui";
import { useAuth } from "../App";

const addMonths = (n, from) => {
  const d = from ? new Date(from + "T00:00:00Z") : new Date();
  const day = d.getUTCDate(); d.setUTCDate(1); d.setUTCMonth(d.getUTCMonth() + n);
  const last = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
  d.setUTCDate(Math.min(day, last)); return d.toISOString().slice(0, 10);
};
const ISSUER = !!LICENSE?.issuer;
const blank = () => ({ name: "", owner_name: "", owner_email: "", owner_password: "", phone: "", address: "", max_devices: 2, max_employees: 50,
  valid_till: addMonths(12), make_license: ISSUER, lock: true });
const fmt = (s) => (s ? new Date(s + "T00:00:00").toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" }) : "—");

function CopyBtn({ text }) {
  const [ok, setOk] = useState(false);
  return <button type="button" className="btn sm ghost" onClick={() => { try { navigator.clipboard.writeText(text); } catch { /* ignore */ } setOk(true); setTimeout(() => setOk(false), 1500); }}>{ok ? "Copied ✓" : "Copy"}</button>;
}

function ShopLicense({ lic, shop, onClose }) {
  const server = window.location.origin;
  const share = () => {
    const txt = `Hayat HRMS licence for ${shop.name}\nMachines: ${lic.machines} · Valid till ${fmt(lic.valid_till)}\n\nLicence key (paste in Activate licence):\n${lic.key}\n\nLicence code: ${lic.code}\nServer: ${server}\n\nHayat Enterprises · 96738 78652`;
    const ph = (shop.phone || "").replace(/\D/g, "").replace(/^(\d{10})$/, "91$1");
    window.open(`https://wa.me/${ph}?text=${encodeURIComponent(txt)}`, "_blank");
  };
  return (
    <Modal title={`Licence — ${shop.name}`} onClose={onClose}
      footer={<><button className="btn ghost" onClick={onClose}>Close</button><button className="btn green" onClick={share}>Send on WhatsApp</button></>}>
      <div className="grid g2" style={{ marginBottom: 10 }}>
        <div><div className="small muted">Licence code</div><div className="mono" style={{ fontSize: 20, fontWeight: 800 }}>{lic.code} <CopyBtn text={lic.code} /></div></div>
        <div><div className="small muted">Valid till</div><div style={{ fontSize: 18, fontWeight: 700 }}>{fmt(lic.valid_till)}</div><div className="small muted">{lic.machines} machine(s){lic.lock ? " · locks to the first computer" : ""}</div></div>
      </div>
      <div className="row" style={{ justifyContent: "space-between" }}><span className="small muted">Licence key — the customer pastes this in “Activate licence” (works without internet)</span><CopyBtn text={lic.key} /></div>
      <textarea readOnly className="mono" rows={6} value={lic.key} style={{ width: "100%", fontSize: 11 }} onFocus={(e) => e.target.select()} />
      <p className="small muted" style={{ marginBottom: 0 }}>The shop's login on this server also follows this validity. After a renewal, send the new key again.</p>
    </Modal>
  );
}

export default function Companies() {
  const { setCompany, reloadCompanies } = useAuth();
  const toast = useToast();
  const ask = useConfirm();
  const [rows, setRows] = useState([]);
  const [unknown, setUnknown] = useState([]);
  const [edit, setEdit] = useState(null);
  const [plat, setPlat] = useState(null);
  const [show, setShow] = useState(null);
  const load = async () => {
    const [a, b] = await Promise.all([api.get("/admin/companies"), api.get("/admin/unknown-devices")]);
    setRows(a.data); setUnknown(b.data);
    api.get("/admin/platform").then((r) => setPlat(r.data)).catch(() => {});
  };
  useEffect(() => { load(); }, []);
  const makeLicense = async (shop, body) => {
    const r = await api.post(`/admin/companies/${shop.id}/license`, body);
    setShow({ lic: r.data, shop }); load(); reloadCompanies();
  };
  const save = async () => {
    try {
      if (edit.id) await api.put("/admin/companies/" + edit.id, edit);
      else {
        const r = await api.post("/admin/companies", edit);
        if (edit.make_license && ISSUER) {
          await makeLicense({ ...r.data, phone: edit.phone }, { valid_till: edit.valid_till, lock: edit.lock, machines: Number(edit.max_devices) || 1 });
        }
      }
      toast("Saved"); setEdit(null); load(); reloadCompanies();
    } catch (e) { toast(errMsg(e), true); }
  };
  const openLicense = async (c) => {
    try {
      const r = await api.get(`/admin/companies/${c.id}/license`);
      if (r.data.license?.key) setShow({ lic: r.data.license, shop: c });
      else await makeLicense(c, { valid_till: c.valid_till || addMonths(12), lock: true });
    } catch (e) { toast(errMsg(e), true); }
  };
  const renew = async (c, months) => {
    try { await makeLicense(c, { months: Number(months) }); toast(`Renewed — new key ready to send`); } catch (e) { toast(errMsg(e), true); }
  };
  const set = (k) => (e) => setEdit({ ...edit, [k]: e.target.type === "checkbox" ? e.target.checked : e.target.value });
  return (
    <>
      <div className="page-head">
        <div><h1>Shops</h1><p>Each shop has its own owner login, biometric devices, employees, salary and WhatsApp settings. Shops can also sign up themselves.</p></div>
        <button className="btn green" onClick={() => setEdit(blank())}>+ New shop</button>
      </div>
      <div className="card flush"><div className="tbl-wrap"><table className="tbl">
        <thead><tr><th>Shop</th><th>Owner login</th><th className="num">Employees</th><th className="num">Devices</th><th>Valid till</th>{ISSUER && <th>Licence</th>}<th>Status</th><th /></tr></thead>
        <tbody>{rows.map((c) => (
          <tr key={c.id}>
            <td style={{ fontWeight: 700 }}>{c.name}<div className="small muted">{c.phone}{c.city ? ` · ${c.city}` : ""}{c.source === "signup" ? " · self sign-up" : ""}</div></td>
            <td>{c.owner?.email}</td>
            <td className="num">{c.employees} / {c.max_employees}</td><td className="num">{c.devices} / {c.max_devices}</td>
            <td>{fmt(c.valid_till)}{c.valid_till && <div className="small" style={{ color: c.valid_till < new Date().toISOString().slice(0, 10) ? "var(--red)" : "var(--muted)" }}>{c.valid_till < new Date().toISOString().slice(0, 10) ? "expired" : `${Math.round((new Date(c.valid_till) - new Date()) / 864e5)} days left`}</div>}</td>
            {ISSUER && <td>
              {c.license ? <button className="btn sm ghost mono" title="Show key" onClick={() => openLicense(c)}>{c.license.code}</button>
                : <button className="btn sm" onClick={() => openLicense(c)}>Make key</button>}
              {c.license && <select className="sm" value="" onChange={(e) => e.target.value && renew(c, e.target.value)} style={{ width: 90, marginLeft: 6 }}>
                <option value="">Renew…</option><option value="1">+1 month</option><option value="3">+3 months</option><option value="6">+6 months</option><option value="12">+1 year</option><option value="24">+2 years</option></select>}
            </td>}
            <td>{c.pending ? <span className="chip s-HD">Awaiting approval</span> : c.active !== false ? <span className="chip s-P">Active</span> : <span className="chip s-A">Suspended</span>}</td>
            <td className="row" style={{ justifyContent: "flex-end" }}>
              <button className="btn sm ghost" onClick={() => setEdit({ ...c, owner_password: "" })}>Edit</button>
              <button className="btn sm" onClick={() => setCompany(c.id)}>Open →</button>
              <button className="btn sm danger" onClick={async () => {
                const r = await ask({ title: `Delete ${c.name}?`, danger: true, okText: "Delete shop", typeToConfirm: c.name,
                  message: "Deletes the shop, its logins, devices, employees, punches, attendance, payroll and WhatsApp logs. This cannot be undone. To stop access but keep data, use Edit → untick Active instead." });
                if (!r) return;
                try { await api.post(`/admin/companies/${c.id}/delete`, { confirm_name: c.name }); toast("Shop deleted"); load(); reloadCompanies(); } catch (e) { toast(errMsg(e), true); }
              }}>Delete</button>
            </td>
          </tr>))}
          {!rows.length && <tr><td colSpan="8" className="empty">No shops yet.</td></tr>}
        </tbody></table></div></div>
      <div className="note" style={{ marginTop: 14 }}>Sign-up settings, the share link and approvals are on the <Link to="/signups">Shop sign-up</Link> page.</div>
      {show && <ShopLicense lic={show.lic} shop={show.shop} onClose={() => setShow(null)} />}
      {unknown.length > 0 && (
        <div className="card" style={{ marginTop: 14 }}>
          <h2>Unregistered ADMS machines calling the server</h2>
          <p className="muted small">Add the serial number to a shop's device list (mode: eSSL ADMS push) to start receiving its punches.</p>
          <table className="tbl"><tbody>{unknown.map((u) => <tr key={u.serial}><td className="mono">{u.serial}</td><td>{u.ip}</td><td className="muted">{ago(u.last_seen)}</td></tr>)}</tbody></table>
        </div>
      )}
      {edit && (
        <Modal title={edit.id ? "Edit shop" : "New shop"} onClose={() => setEdit(null)}
          footer={<><button className="btn ghost" onClick={() => setEdit(null)}>Cancel</button><button className="btn green" onClick={save}>Save</button></>}>
          <div className="grid g2">
            <F label="Shop name *"><input value={edit.name} onChange={set("name")} /></F>
            <F label="Phone"><input value={edit.phone || ""} onChange={set("phone")} /></F>
            <F label="Address" span={2}><input value={edit.address || ""} onChange={set("address")} /></F>
            {!edit.id && <F label="Owner name"><input value={edit.owner_name} onChange={set("owner_name")} /></F>}
            {!edit.id && <F label="Owner login email *"><input value={edit.owner_email} onChange={set("owner_email")} /></F>}
            <F label={edit.id ? "Reset owner password (leave blank to keep)" : "Owner password *"}><input value={edit.owner_password} onChange={set("owner_password")} /></F>
            <F label="Valid till (subscription / licence)"><input type="date" value={edit.valid_till || ""} onChange={set("valid_till")} /></F>
            <div className="f"><span className="label">Validity</span><div className="row" style={{ gap: 6 }}>
              {[[1, "1 month"], [3, "3 months"], [6, "6 months"], [12, "1 year"], [24, "2 years"]].map(([m, l]) => (
                <button type="button" key={m} className={"btn sm " + (edit.valid_till === addMonths(m) ? "" : "ghost")} onClick={() => setEdit({ ...edit, valid_till: addMonths(m) })}>{l}</button>))}
            </div></div>
            <F label="Max devices"><input type="number" value={edit.max_devices} onChange={set("max_devices")} /></F>
            <F label="Max employees"><input type="number" value={edit.max_employees} onChange={set("max_employees")} /></F>
            {edit.id && <label className="check"><input type="checkbox" checked={edit.active !== false} onChange={set("active")} /> Active (untick to suspend)</label>}
            {!edit.id && ISSUER && <div style={{ gridColumn: "span 2" }} className={"opt" + (edit.make_license ? " on" : "")}>
              <input type="checkbox" checked={!!edit.make_license} onChange={set("make_license")} />
              <div><b>Generate licence key for this shop</b>
                <div className="small muted">Valid till the date above, for {edit.max_devices || 1} machine(s). Use it when the shop installs Hayat HRMS on its own computer.</div>
                {edit.make_license && <label className="check" style={{ marginTop: 6 }}><input type="checkbox" checked={!!edit.lock} onChange={set("lock")} /> Lock to one computer</label>}
              </div></div>}
            {edit.id && ISSUER && edit.license && <div className="note" style={{ gridColumn: "span 2" }}>Changing “Valid till” or “Max devices” also updates this shop's licence {edit.license.code}. Send the new key from the Licence column after saving.</div>}
          </div>
        </Modal>
      )}
    </>
  );
}
