import React, { useEffect, useState } from "react";
import { api, errMsg, today, inr, download } from "../api";
import { Modal, F, useToast } from "../ui";

/* Excel · PDF · CSV buttons for one report. path like "/reports/payroll", query like "month=2026-09" */
export function ExportButtons({ path, query = "", name, disabled, small = true }) {
  const toast = useToast();
  const [busy, setBusy] = useState("");
  const get = async (fmt) => {
    setBusy(fmt);
    try { await download(`${path}.${fmt}${query ? "?" + query : ""}`, `${name}.${fmt}`); } catch (e) { toast(errMsg(e), true); }
    setBusy("");
  };
  const cls = "btn ghost" + (small ? " sm" : "");
  return (
    <div className="export-btns">
      <button className={cls} disabled={disabled || !!busy} onClick={() => get("xlsx")} title="Download Excel">
        <span className="ft xls">XLS</span>{busy === "xlsx" ? "…" : "Excel"}</button>
      <button className={cls} disabled={disabled || !!busy} onClick={() => get("pdf")} title="Download PDF">
        <span className="ft pdf">PDF</span>{busy === "pdf" ? "…" : "PDF"}</button>
      <button className={cls} disabled={disabled || !!busy} onClick={() => get("csv")} title="Download CSV">CSV</button>
    </div>
  );
}

/* Give a new advance. employee optional (pre-selected). */
export function GiveAdvance({ employee, onClose, onDone }) {
  const toast = useToast();
  const [emps, setEmps] = useState(employee ? [employee] : []);
  const [f, setF] = useState({ employee_id: employee?.id || "", amount: "", mode: "ask", installment: "", date: today(), note: "" });
  const [busy, setBusy] = useState(false);
  useEffect(() => { if (!employee) api.get("/employees").then((r) => setEmps(r.data)); }, [employee]);
  const save = async () => {
    if (!f.employee_id) return toast("Select the employee", true);
    if (!(Number(f.amount) > 0)) return toast("Enter the advance amount", true);
    if (f.mode === "auto" && !(Number(f.installment) > 0)) return toast("Enter how much to cut every month", true);
    setBusy(true);
    try {
      await api.post("/advances", { employee_id: f.employee_id, amount: f.amount, date: f.date, note: f.note,
        installment: f.mode === "auto" ? f.installment : "" });
      toast("Advance saved"); onDone && onDone(); onClose();
    } catch (e) { toast(errMsg(e), true); }
    setBusy(false);
  };
  const months = f.mode === "auto" && Number(f.installment) > 0 ? Math.ceil(Number(f.amount || 0) / Number(f.installment)) : 0;
  return (
    <Modal title="Give advance / loan" onClose={onClose}
      footer={<><button className="btn ghost" onClick={onClose}>Cancel</button><button className="btn green" disabled={busy} onClick={save}>{busy ? "Saving…" : "Save advance"}</button></>}>
      <div className="grid">
        <F label="Employee">
          <select value={f.employee_id} disabled={!!employee} onChange={(e) => setF({ ...f, employee_id: e.target.value })}>
            <option value="">Select employee</option>
            {emps.map((e) => <option key={e.id} value={e.id}>{e.code} — {e.name}</option>)}
          </select>
        </F>
        <div className="grid g2">
          <F label="Amount ₹"><input type="number" min="0" value={f.amount} onChange={(e) => setF({ ...f, amount: e.target.value })} autoFocus /></F>
          <F label="Date given"><input type="date" value={f.date} onChange={(e) => setF({ ...f, date: e.target.value })} /></F>
        </div>
        <div className="label">How to recover it from salary</div>
        <label className={"opt" + (f.mode === "ask" ? " on" : "")}><input type="radio" checked={f.mode === "ask"} onChange={() => setF({ ...f, mode: "ask" })} />
          <div><b>Ask me every month</b><div className="small muted">At salary time you type how much to cut (or 0 to skip that month).</div></div></label>
        <label className={"opt" + (f.mode === "auto" ? " on" : "")}><input type="radio" checked={f.mode === "auto"} onChange={() => setF({ ...f, mode: "auto" })} />
          <div style={{ flex: 1 }}><b>Fixed monthly installment (automatic)</b><div className="small muted">Cut the same amount every month until cleared — you can still change any month.</div>
            {f.mode === "auto" && <div className="row" style={{ marginTop: 8 }}>
              <input type="number" min="0" placeholder="₹ per month" value={f.installment} onChange={(e) => setF({ ...f, installment: e.target.value })} style={{ maxWidth: 150 }} />
              {months > 0 && <span className="small muted">≈ {months} month{months > 1 ? "s" : ""}</span>}
            </div>}
          </div></label>
        <F label="Note (optional)"><input value={f.note} onChange={(e) => setF({ ...f, note: e.target.value })} placeholder="e.g. medical, festival" /></F>
      </div>
    </Modal>
  );
}

/* Per-advance "cut this month" editor. rows: from /payroll/advances. value: {advance_id: amount|""} */
export function AdvanceCutTable({ rows, value, onChange, showEmployee = true }) {
  if (!rows.length) return <div className="muted small">No open advance.</div>;
  return (
    <table className="tbl">
      <thead><tr>{showEmployee && <th>Employee</th>}<th>Given</th><th className="num">Balance</th><th>Plan</th><th className="num" style={{ width: 150 }}>Cut this month ₹</th></tr></thead>
      <tbody>{rows.map((a) => {
        const v = value[a.advance_id];
        const auto = a.auto && a.installment > 0;
        const locked = a.slip_status === "final" || !a.slip_id;
        return (
          <tr key={a.advance_id}>
            {showEmployee && <td style={{ fontWeight: 600 }}>{a.employee_name} <span className="mono muted">{a.emp_code}</span>{a.net != null && <div className="small muted">net {inr(a.net)}</div>}</td>}
            <td className="small"><span className="mono">{a.date}</span> · {inr(a.amount)}{a.note && <div className="muted">{a.note}</div>}</td>
            <td className="num" style={{ fontWeight: 700 }}>{inr(a.balance)}</td>
            <td className="small">{auto ? <>auto {inr(a.installment)}/mo</> : <span className="chip s-HD">ask monthly</span>}</td>
            <td className="num">
              {locked ? <span className="small muted">{a.slip_id ? `final · ${inr(a.this_month)}` : "no slip yet"}</span> :
                <input type="number" min="0" max={a.balance} value={v ?? ""} placeholder={auto ? `auto ${a.installment}` : "0"}
                  onChange={(e) => onChange({ ...value, [a.advance_id]: e.target.value })} style={{ width: 120, textAlign: "right" }} />}
            </td>
          </tr>);
      })}</tbody>
    </table>
  );
}

/* Month-wide "how much advance to cut" screen. */
export function AdvanceDeductions({ month, onClose, onDone, intro }) {
  const toast = useToast();
  const [rows, setRows] = useState(null);
  const [val, setVal] = useState({});
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    api.get("/payroll/advances?month=" + month).then((r) => {
      setRows(r.data);
      setVal(Object.fromEntries(r.data.map((a) => [a.advance_id, a.chosen != null ? String(a.chosen) : ""])));
    });
  }, [month]);
  const save = async () => {
    setBusy(true);
    try {
      const amounts = {};
      rows.forEach((a) => { if (a.slip_id && a.slip_status !== "final") amounts[a.advance_id] = val[a.advance_id] ?? ""; });
      const r = await api.post("/payroll/advance-deductions", { month, amounts });
      toast(`${r.data.updated} salary slip(s) updated`); onDone && onDone(); onClose();
    } catch (e) { toast(errMsg(e), true); }
    setBusy(false);
  };
  const total = (rows || []).reduce((s, a) => {
    const v = val[a.advance_id];
    return s + (v === "" || v == null ? (a.auto ? Math.min(a.installment || 0, a.balance) : 0) : Math.min(Number(v) || 0, a.balance));
  }, 0);
  return (
    <Modal wide title={`Advance deductions — ${month}`} onClose={onClose}
      footer={<><span className="small muted" style={{ marginRight: "auto" }}>Total to cut ≈ <b>{inr(total)}</b></span>
        <button className="btn ghost" onClick={onClose}>Cancel</button>
        <button className="btn green" disabled={busy || !rows?.length} onClick={save}>{busy ? "Saving…" : "Save & recalculate slips"}</button></>}>
      {intro && <div className="note" style={{ marginBottom: 12 }}>{intro}</div>}
      <p className="small muted" style={{ marginTop: 0 }}>Type the amount to cut from this month's salary. <b>0</b> = skip this month. Leave blank to use the automatic installment (if the advance has one). It never cuts more than the salary.</p>
      {!rows ? <div className="empty">Loading…</div> : !rows.length ? <div className="empty">No employee has an open advance.</div> :
        <div className="tbl-wrap"><AdvanceCutTable rows={rows} value={val} onChange={setVal} /></div>}
    </Modal>
  );
}

/* Edit an existing advance (plan, note, amount) + record cash repayment */
export function EditAdvance({ adv, onClose, onDone }) {
  const toast = useToast();
  const [f, setF] = useState({ amount: adv.amount, installment: adv.auto && adv.installment ? adv.installment : "", note: adv.note || "", date: adv.date });
  const [cash, setCash] = useState("");
  const go = async (fn, msg) => { try { await fn(); toast(msg); onDone && onDone(); onClose(); } catch (e) { toast(errMsg(e), true); } };
  return (
    <Modal title={`Advance — ${adv.employee_name}`} onClose={onClose}
      footer={<><button className="btn ghost" onClick={onClose}>Close</button><button className="btn green" onClick={() => go(() => api.put("/advances/" + adv.id, f), "Advance updated")}>Save</button></>}>
      <div className="grid">
        <div className="grid g2">
          <F label="Amount ₹"><input type="number" value={f.amount} onChange={(e) => setF({ ...f, amount: e.target.value })} /></F>
          <F label="Date"><input type="date" value={f.date} onChange={(e) => setF({ ...f, date: e.target.value })} /></F>
        </div>
        <F label="Monthly installment ₹ (blank = ask me every month)"><input type="number" value={f.installment} placeholder="ask every month" onChange={(e) => setF({ ...f, installment: e.target.value })} /></F>
        <F label="Note"><input value={f.note} onChange={(e) => setF({ ...f, note: e.target.value })} /></F>
        <div className="note">Balance <b>{inr(adv.balance)}</b> · recovered {inr(adv.amount - adv.balance)}</div>
        {adv.balance > 0 && <div className="row">
          <input type="number" placeholder="₹ paid back in cash" value={cash} onChange={(e) => setCash(e.target.value)} style={{ maxWidth: 190 }} />
          <button className="btn sm" disabled={!(Number(cash) > 0)} onClick={() => go(() => api.post(`/advances/${adv.id}/repay`, { amount: cash }), "Cash repayment recorded")}>Record cash repayment</button>
        </div>}
        {adv.recoveries?.length > 0 && <table className="tbl"><thead><tr><th>Recovered</th><th className="num">Amount</th></tr></thead>
          <tbody>{adv.recoveries.map((r, i) => <tr key={i}><td className="small">{r.cash ? `Cash · ${r.date}` : `Salary ${r.month}`}</td><td className="num">{inr(r.amount)}</td></tr>)}</tbody></table>}
      </div>
    </Modal>
  );
}
