import React, { useEffect, useRef, useState } from "react";
import { api, errMsg, store } from "../api";
import { Modal, F, useToast, useConfirm } from "../ui";

const ROLE = { superadmin: "Super admin", owner: "Owner", manager: "Manager / HR" };

export default function AccountMenu({ me, company, logout }) {
  const toast = useToast();
  const ask = useConfirm();
  const [open, setOpen] = useState(false);
  const [pw, setPw] = useState(null);
  const ref = useRef(null);
  useEffect(() => {
    const close = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", close);
    return () => document.removeEventListener("mousedown", close);
  }, []);
  const u = me.user;
  const ini = (u.name || u.email || "?").split(" ").map((w) => w[0]).slice(0, 2).join("").toUpperCase();
  const outAll = async () => {
    setOpen(false);
    if (!(await ask({ title: "Log out of all devices?", okText: "Log out everywhere", message: "Every phone and computer signed in with this login is logged out. You stay signed in here." }))) return;
    try { const r = await api.post("/auth/logout-all"); store.set("hrms_token", r.data.token); toast("Logged out of all other devices"); }
    catch (e) { toast(errMsg(e), true); }
  };
  const changePw = async () => {
    try {
      const r = await api.post("/auth/change-password", pw);
      if (r.data.token) store.set("hrms_token", r.data.token);
      toast("Password changed — other devices are logged out"); setPw(null);
    } catch (e) { toast(errMsg(e), true); }
  };
  return (
    <div className="acct" ref={ref}>
      <button className="acct-btn" onClick={() => setOpen(!open)} aria-expanded={open} aria-haspopup="menu">
        <span className="acct-ini">{ini}</span><span className="acct-name">{u.name}</span>
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4"><path d="m6 9 6 6 6-6" /></svg>
      </button>
      {open && (
        <div className="acct-menu" role="menu">
          <div className="acct-head"><b>{u.name}</b><div className="small muted">{u.email}</div>
            <div className="small" style={{ marginTop: 4 }}><span className="chip s-WO">{ROLE[u.role] || u.role}</span>{company && <span className="muted"> · {company.name}</span>}</div></div>
          <button role="menuitem" onClick={() => { setOpen(false); setPw({ old_password: "", new_password: "", confirm: "" }); }}>Change password</button>
          <button role="menuitem" onClick={outAll}>Log out of all devices</button>
          <button role="menuitem" className="danger" onClick={logout}>Log out</button>
        </div>
      )}
      {pw && (
        <Modal title="Change password" onClose={() => setPw(null)}
          footer={<><button className="btn ghost" onClick={() => setPw(null)}>Cancel</button>
            <button className="btn green" disabled={!pw.old_password || pw.new_password.length < 6 || pw.new_password !== pw.confirm} onClick={changePw}>Change password</button></>}>
          <div className="grid" style={{ maxWidth: 360 }}>
            <F label="Current password"><input id="pw-old" type="password" value={pw.old_password} onChange={(e) => setPw({ ...pw, old_password: e.target.value })} autoFocus /></F>
            <F label="New password (6+ characters)"><input id="pw-new" type="password" value={pw.new_password} onChange={(e) => setPw({ ...pw, new_password: e.target.value })} /></F>
            <F label="Type new password again"><input id="pw-new2" type="password" value={pw.confirm} onChange={(e) => setPw({ ...pw, confirm: e.target.value })} /></F>
            {pw.confirm && pw.confirm !== pw.new_password && <div className="small" style={{ color: "var(--red)" }}>The two new passwords don't match.</div>}
          </div>
        </Modal>
      )}
    </div>
  );
}
