import React, { useEffect, useState } from "react";
import { api, errMsg, today } from "../api";
import { F, useToast, useConfirm, Copy } from "../ui";

const VARS = {
  punch_alert: "{name} {direction} {time} {date} {company}",
  late_alert: "{name} {date} {time} {late_minutes} {company}",
  absent_alert: "{name} {date} {company}",
  daily_summary: "{company} {date} {total} {present} {absent} {late} {absent_names}",
  payslip: "{name} {month} {company} {net} {link}",
  monthly_summary: "{company} {month} {employees} {total_net}",
};

/** Body text with {{n}} replaced by the sample values — what the employee will actually read. */
const preview = (m) => (m.body || "").replace(/\{\{(\d+)\}\}/g, (_, n) => m.samples?.[n - 1] ?? `{{${n}}}`);

function TemplateCard({ k, m, onUse }) {
  return (
    <div className="tpl">
      <div className="row" style={{ marginBottom: 8 }}>
        <b style={{ flex: 1 }}>{m.label}</b>
        <span className="chip s-P">Utility</span><span className="chip s-WO">English</span>
        <button className="btn sm ghost" onClick={onUse}>Use in app</button>
      </div>
      <div className="tpl-grid">
        <span className="muted small">Template name</span><Copy text={m.template} />
        <span className="muted small">Category</span><span>UTILITY</span>
        <span className="muted small">Header</span><span>{m.header}</span>
        <span className="muted small">Body</span><Copy text={m.body} />
        <span className="muted small">Footer</span><Copy text={m.footer} />
        <span className="muted small">Buttons</span><span>None</span>
        <span className="muted small">Sample values</span><span className="small">{m.samples.map((v, i) => <span key={i} className="mono" style={{ marginRight: 10 }}>{`{{${i + 1}}}`} = {v}</span>)}</span>
      </div>
      <div className="wa-bubble"><div className="small muted" style={{ marginBottom: 4 }}>Preview</div>{preview(m)}<div className="small muted" style={{ marginTop: 6 }}>{m.footer}</div></div>
    </div>
  );
}

export default function WhatsApp() {
  const toast = useToast();
  const ask = useConfirm();
  const [tab, setTab] = useState("msgs");
  const [w, setW] = useState(null);
  const [meta, setMeta] = useState({});
  const [logs, setLogs] = useState([]);
  const [test, setTest] = useState({ phone: "", template: "", params: "", media_url: "" });
  const [testRes, setTestRes] = useState(null);
  const load = async () => {
    const [s, c] = await Promise.all([api.get("/whatsapp/settings"), api.get("/company")]);
    setW(s.data); setMeta(c.data.whatsapp_events_meta);
  };
  useEffect(() => { load(); }, []);
  useEffect(() => { if (tab === "logs") api.get("/whatsapp/logs").then((r) => setLogs(r.data)); }, [tab]);
  if (!w) return null;
  const save = async () => { try { const r = await api.put("/whatsapp/settings", w); setW(r.data); toast("WhatsApp settings saved"); } catch (e) { toast(errMsg(e), true); } };
  const set = (k) => (e) => setW({ ...w, [k]: e.target.type === "checkbox" ? e.target.checked : e.target.value });
  const setEv = (k, f, v) => setW({ ...w, events: { ...w.events, [k]: { ...w.events[k], [f]: v } } });
  const useAll = () => {
    const ev = { ...w.events };
    Object.entries(meta).forEach(([k, m]) => { ev[k] = { ...ev[k], template: m.template, params: m.params }; });
    setW({ ...w, events: ev });
    toast("Recommended template names and variables filled — click Save");
  };
  const runNow = async (event) => {
    try { const r = await api.post("/whatsapp/run", { event, date: today() }); toast(`${r.data.count} message(s) processed — see Logs`); }
    catch (e) { toast(errMsg(e), true); }
  };
  return (
    <>
      <div className="page-head">
        <div><h1>WhatsApp messages</h1><p>Sent through your BhashSMS WhatsApp panel using approved templates.</p></div>
        <div className="row">
          <label className="check" style={{ fontWeight: 700 }}><input type="checkbox" checked={!!w.enabled} onChange={set("enabled")} /> WhatsApp ON</label>
          <button className="btn green" onClick={save}>Save</button>
        </div>
      </div>
      <div className="tabs">{[["msgs", "Messages"], ["templates", "Templates to submit"], ["panel", "BhashSMS panel"], ["test", "Test send"], ["logs", "Logs"]].map(([k, l]) => <button key={k} className={tab === k ? "on" : ""} onClick={() => setTab(k)}>{l}</button>)}</div>

      {tab === "msgs" && (
        <>
          <div className="card" style={{ marginBottom: 14 }}>
            <div className="grid g4">
              <F label="Owner WhatsApp numbers (comma)"><input value={w.owner_numbers} onChange={set("owner_numbers")} placeholder="98xxxxxxxx, 97xxxxxxxx" /></F>
              <F label="Daily summary time"><input type="time" value={w.daily_summary_time} onChange={set("daily_summary_time")} /></F>
              <F label="Absent alert time"><input type="time" value={w.absent_alert_time} onChange={set("absent_alert_time")} /></F>
              <F label="Live alert only if punch is within (min)"><input type="number" value={w.realtime_window_minutes} onChange={set("realtime_window_minutes")} /></F>
            </div>
          </div>
          <div className="note" style={{ marginBottom: 14, display: "flex", gap: 12, alignItems: "center", flexWrap: "wrap" }}>
            <span style={{ flex: 1, minWidth: 260 }}>Submit the 6 ready-made <b>Utility</b> templates in your BhashSMS panel (see <b>Templates to submit</b>), then fill their names here in one click.</span>
            <button className="btn sm" onClick={useAll}>Use recommended templates</button>
          </div>
          <div className="card flush"><table className="tbl">
            <thead><tr><th>On</th><th>Message</th><th>Template name (as approved in BhashSMS)</th><th>Template variables, in order</th><th /></tr></thead>
            <tbody>{Object.entries(meta).map(([k, m]) => (
              <tr key={k}>
                <td><input type="checkbox" checked={!!w.events[k]?.enabled} onChange={(e) => setEv(k, "enabled", e.target.checked)} /></td>
                <td style={{ fontWeight: 600 }}>{m.label}<div className="small muted">to {m.to}</div></td>
                <td><input value={w.events[k]?.template || ""} onChange={(e) => setEv(k, "template", e.target.value)} placeholder="template_name" /></td>
                <td><input className="mono" value={w.events[k]?.params || ""} onChange={(e) => setEv(k, "params", e.target.value)} />
                  <div className="small muted">available: {VARS[k]}</div></td>
                <td>{["daily_summary", "absent_alert"].includes(k) && <button className="btn sm ghost" onClick={() => runNow(k)}>Send now</button>}</td>
              </tr>))}</tbody></table></div>
          <p className="small muted" style={{ marginTop: 10 }}>Variables map to {"{{1}}, {{2}}…"} of your template in the same order. Salary slip messages also attach the PDF (document header template). Save before using “Send now”.</p>
        </>
      )}

      {tab === "templates" && (
        <>
          <div className="note" style={{ marginBottom: 14, lineHeight: 1.6 }}>
            <b>How to submit:</b> BhashSMS panel → WhatsApp → Templates → Create. For each template below choose
            category <b>Utility</b>, language <b>English</b>, paste the name, body and footer exactly, set the header,
            and enter the sample values. Approval usually takes from a few minutes to 24 hours. Utility templates must stay
            transactional — don't add offers, discounts or "visit our shop" lines, or Meta will reclassify them as Marketing.
          </div>
          <div className="grid" style={{ gap: 14 }}>
            {Object.entries(meta).map(([k, m]) => <TemplateCard key={k} k={k} m={m} onUse={() => { setW((x) => ({ ...x, events: { ...x.events, [k]: { ...x.events[k], template: m.template, params: m.params } } })); toast("Filled — click Save"); }} />)}
          </div>
        </>
      )}

      {tab === "panel" && (
        <div className="card">
          <div className="grid g3">
            <F label="BhashSMS username"><input value={w.user} onChange={set("user")} /></F>
            <F label="Password (blank = keep)"><input type="password" value={w.password} onChange={set("password")} /></F>
            <F label="Sender"><input value={w.sender} onChange={set("sender")} /></F>
            <F label="API URL template" span={3}><textarea rows="3" className="mono" value={w.url_template} onChange={set("url_template")} /></F>
            <F label="Added for PDF / image messages" span={3}><input className="mono" value={w.media_suffix} onChange={set("media_suffix")} /></F>
          </div>
          <p className="small muted" style={{ marginTop: 10 }}>Placeholders: {"{user} {pass} {sender} {phone} {template} {params} {media_type} {media_url}"}. Copy the exact API format from your BhashSMS panel’s API page if it differs.</p>
        </div>
      )}

      {tab === "test" && (
        <div className="card" style={{ maxWidth: 640 }}>
          <div className="grid">
            <F label="Mobile"><input value={test.phone} onChange={(e) => setTest({ ...test, phone: e.target.value })} /></F>
            <F label="Template name"><input value={test.template} onChange={(e) => setTest({ ...test, template: e.target.value })} /></F>
            <F label="Params (comma separated)"><input value={test.params} onChange={(e) => setTest({ ...test, params: e.target.value })} /></F>
            <F label="Media URL (optional, for document templates)"><input value={test.media_url} onChange={(e) => setTest({ ...test, media_url: e.target.value })} /></F>
            <button className="btn green" onClick={async () => { try { const r = await api.post("/whatsapp/test", test); setTestRes(r.data); } catch (e) { toast(errMsg(e), true); } }}>Send test</button>
            {testRes && <div className={"note " + (testRes.status === "sent" ? "ok" : "warn")}><b>{testRes.status}</b> — {testRes.response}</div>}
          </div>
        </div>
      )}

      {tab === "logs" && (
        <div className="card flush">
          <div className="card-head"><span className="small muted">{logs.length} messages</span>
            <button className="btn sm danger" disabled={!logs.length} onClick={async () => {
              if (!(await ask({ title: "Clear all WhatsApp logs?", danger: true, okText: "Clear logs", message: "Only the history list is cleared; messages already sent are not affected." }))) return;
              await api.delete("/whatsapp/logs"); setLogs([]); toast("Logs cleared");
            }}>Clear logs</button></div>
          <div className="tbl-wrap"><table className="tbl">
          <thead><tr><th>Time</th><th>Type</th><th>Mobile</th><th>Template</th><th>Params</th><th>Status</th><th>Response</th></tr></thead>
          <tbody>{logs.map((l) => (
            <tr key={l.id}><td className="mono small">{new Date(l.created_at).toLocaleString("en-IN")}</td><td>{l.event}</td><td className="mono">{l.phone}</td><td>{l.template}</td>
              <td className="small" style={{ maxWidth: 260, overflow: "hidden", textOverflow: "ellipsis" }}>{l.params}</td>
              <td><span className={"chip " + (l.status === "sent" ? "s-P" : l.status === "skipped" ? "s-WO" : "s-A")}>{l.status}</span></td>
              <td className="small muted">{l.response}</td></tr>))}
            {!logs.length && <tr><td colSpan="7" className="empty">No messages yet.</td></tr>}</tbody></table></div></div>
      )}
    </>
  );
}
