import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api, ago } from "../api";

export default function Dashboard() {
  const [d, setD] = useState(null);
  const load = () => api.get("/dashboard").then((r) => setD(r.data)).catch(() => {});
  useEffect(() => { load(); const t = setInterval(load, 30000); return () => clearInterval(t); }, []);
  if (!d) return <div className="muted">Loading…</div>;
  const s = d.stats;
  const pct = (n) => (s.total ? Math.round((n / s.total) * 100) : 0);
  const cards = [
    ["Present today", s.present, "var(--mint)"],
    ["Not in yet", s.not_yet, "#a0a8b8"],
    ["Absent", s.absent, "var(--red)"],
    ["Late arrivals", s.late, "var(--amber)"],
  ];
  const max = Math.max(1, ...d.trend.map((t) => t.present + t.absent));
  return (
    <>
      <div className="page-head">
        <div><h1>Today at a glance</h1><p>{s.total} employees · updated {d.time} · auto-refresh every 30 s</p></div>
        <div className="row"><span className="chip s-L">{s.on_leave} on leave</span><span className="chip s-WO">{s.off} off / holiday</span></div>
      </div>
      <div className="grid g4" style={{ marginBottom: 14 }}>
        {cards.map(([k, v, c]) => (
          <div className="card stat" key={k}><div className="k">{k}</div><div className="v">{v}</div>
            <div className="bar"><i style={{ width: pct(v) + "%", background: c }} /></div></div>
        ))}
      </div>
      <div className="grid g3">
        <div className="card flush" style={{ gridColumn: "span 2" }}>
          <div className="card-head"><h2>Live punches</h2><Link to="/punches" className="small">All logs →</Link></div>
          <div className="tbl-wrap"><table className="tbl"><thead><tr><th>Time</th><th>Employee</th><th>ID</th><th>Device</th><th>Source</th></tr></thead>
            <tbody>
              {d.recent.map((p) => (
                <tr key={p.id}><td className="mono">{p.ts.slice(5, 16).replace("-", "/")}</td>
                  <td style={{ fontWeight: 600, color: p.employee_name === "Unregistered ID" ? "var(--red)" : undefined }}>{p.employee_name}</td>
                  <td className="mono">{p.emp_code}</td><td>{p.device_name}</td><td className="small muted">{p.source}</td></tr>
              ))}
              {!d.recent.length && <tr><td colSpan="5" className="empty">No punches received yet. Add a device under Biometric devices.</td></tr>}
            </tbody></table></div>
        </div>
        <div className="grid" style={{ alignContent: "start" }}>
          <div className="card">
            <h2>Devices</h2>
            {d.devices.map((v) => (
              <div key={v.id} className="row" style={{ padding: "7px 0", borderBottom: "1px solid #f0f2f5" }}>
                <span className={"dot " + (v.status || "new")} /><b style={{ flex: 1 }}>{v.name}</b>
                <span className="small muted">{v.status === "online" ? "online" : ago(v.last_seen)}</span>
              </div>
            ))}
            {!d.devices.length && <p className="muted">No devices yet. <Link to="/devices">Add one →</Link></p>}
            {d.device_user_count > 0 && <div className="note warn" style={{ marginTop: 10 }}>{d.device_user_count} machine IDs are not linked to employees. <Link to="/employees?tab=device">Add them →</Link></div>}
          </div>
          <div className="card">
            <h2>Last 7 days</h2>
            <div className="trend">
              {d.trend.map((t) => (
                <div className="col" key={t.date}>
                  <div className="bars" style={{ height: "100%" }}>
                    <i style={{ height: (t.present / max) * 100 + "%", background: "var(--mint)" }} title={`${t.present} present`} />
                    <i style={{ height: (t.absent / max) * 100 + "%", background: "#f4a5a7" }} title={`${t.absent} absent`} />
                  </div>
                  <small>{new Date(t.date).toLocaleDateString("en-IN", { weekday: "narrow" })}</small>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
      {d.late_list.length > 0 && (
        <div className="card flush" style={{ marginTop: 14 }}>
          <div className="card-head"><h2>Late today</h2></div>
          <table className="tbl"><tbody>{d.late_list.map((r) => (
            <tr key={r.employee_id}><td style={{ fontWeight: 600 }}>{r.employee_name}</td><td className="mono">In {r.in_time}</td>
              <td><span className="chip s-HD">{r.late_minutes} min late</span></td></tr>))}</tbody></table>
        </div>
      )}
    </>
  );
}
